INSERT INTO omens (id) VALUES ('0e33d572-9a45-494b-91d0-aaf71a4029f7');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('上梁', '0e33d572-9a45-494b-91d0-aaf71a4029f7');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('0e33d572-9a45-494b-91d0-aaf71a4029f7', 'en', 'Lock in the final details of your plan today.', 'Ancient ''Raising the Beam'' marks the structural completion. Modernly, it is the best time to finalize your project framework or core strategy.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('0e33d572-9a45-494b-91d0-aaf71a4029f7', 'zh', '今日宜为你的计划敲定最后的细节。', '古代‘上梁’标志着结构完工。现代语境下，这是敲定项目框架或核心策略的最佳时机。');
INSERT INTO omens (id) VALUES ('66a2a559-cec1-401c-83b5-63cc557cec77');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('上梁', '66a2a559-cec1-401c-83b5-63cc557cec77');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('66a2a559-cec1-401c-83b5-63cc557cec77', 'en', 'Celebrate a major milestone with your team.', 'This was a community celebration of progress. Acknowledging a milestone today boosts morale and solidifies future success.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('66a2a559-cec1-401c-83b5-63cc557cec77', 'zh', '今日宜与团队一起庆祝阶段性成果。', '这是一个庆祝进展的时刻。今日确认阶段性里程碑能提振士气，巩固未来的成功。');
INSERT INTO omens (id) VALUES ('251d1806-b6ce-4790-b91a-80742d84f57a');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('习艺', '251d1806-b6ce-4790-b91a-80742d84f57a');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('251d1806-b6ce-4790-b91a-80742d84f57a', 'en', 'Sign up for that online course or tutorial.', 'Anciently for apprenticeships; today, your brain is primed for absorbing high-level technical skills or new software.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('251d1806-b6ce-4790-b91a-80742d84f57a', 'zh', '立刻报名那个你观望已久的在线课程。', '古代指拜师学艺；今日你的大脑处于接收状态，适合攻克高难度技术或新软件。');
INSERT INTO omens (id) VALUES ('dfbcda8d-3e17-46db-a66d-21ea34081c79');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('习艺', 'dfbcda8d-3e17-46db-a66d-21ea34081c79');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('dfbcda8d-3e17-46db-a66d-21ea34081c79', 'en', 'Spend one hour practicing a difficult technique.', 'Focused repetition today leads to mastery. Don''t just watch; do the work to build muscle memory.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('dfbcda8d-3e17-46db-a66d-21ea34081c79', 'zh', '花一小时专注练习一项高难度技能。', '今日的专注练习能让你迅速精进。不要只是看，亲自动手才能建立肌肉记忆。');
INSERT INTO omens (id) VALUES ('d5b02c97-b6db-494a-b9e5-f770140cc873');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('买房', 'd5b02c97-b6db-494a-b9e5-f770140cc873');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('d5b02c97-b6db-494a-b9e5-f770140cc873', 'en', 'Invest in a high-quality item for your home.', 'Buying property is about long-term stability. Even a small quality investment today strengthens your sense of ''home''.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('d5b02c97-b6db-494a-b9e5-f770140cc873', 'zh', '为家里添置一件能提升幸福感的高质感好物。', '置产关乎长期稳定。今日即便是一份小的高质感投资，也能增强你的“归属感”。');
INSERT INTO omens (id) VALUES ('412da2c7-b757-4ec7-8d23-405c8f90cd9c');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('买房', '412da2c7-b757-4ec7-8d23-405c8f90cd9c');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('412da2c7-b757-4ec7-8d23-405c8f90cd9c', 'en', 'Research long-term assets or investment funds.', 'An auspicious day for committing to your future security. Look for stability over quick wins.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('412da2c7-b757-4ec7-8d23-405c8f90cd9c', 'zh', '调研长期资产或投资基金。', '这是为未来安全感做承诺的吉日。寻找稳健的资产，而非短期快钱。');
INSERT INTO omens (id) VALUES ('5f009b30-e8f7-455a-8d79-1fd43077aa88');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('买衣服', '5f009b30-e8f7-455a-8d79-1fd43077aa88');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('5f009b30-e8f7-455a-8d79-1fd43077aa88', 'en', 'Dress for the job you want, not the one you have.', 'Ancient ''Tailoring'' was about creating a social identity. Refresh your look to align with your next career move.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('5f009b30-e8f7-455a-8d79-1fd43077aa88', 'zh', '穿上那套让你最自信的衣服去面对挑战。', '古代‘裁制’是为了确立社会身份。更新形象，让你的外在与职业野心相匹配。');
INSERT INTO omens (id) VALUES ('397aa846-fc5a-4afb-893d-1ac5a144b54f');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('买衣服', '397aa846-fc5a-4afb-893d-1ac5a144b54f');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('397aa846-fc5a-4afb-893d-1ac5a144b54f', 'en', 'Invest in a high-quality ''uniform'' for work.', 'Your outer armor affects your inner confidence. Today is lucky for selecting clothes that project power.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('397aa846-fc5a-4afb-893d-1ac5a144b54f', 'zh', '为职场表现投资一套高质感的‘战袍’。', '外在的甲胄影响内在的自信。今日宜选择那些能展现专业力量的服饰。');
INSERT INTO omens (id) VALUES ('790e893f-7d94-41f1-ab77-59353fff9754');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('买车', '790e893f-7d94-41f1-ab77-59353fff9754');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('790e893f-7d94-41f1-ab77-59353fff9754', 'en', 'Upgrade your digital workflow or subscription.', 'Ancient ''Vehicles'' expanded human reach. Modernly, tools that speed up your work are your new ''transportation''.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('790e893f-7d94-41f1-ab77-59353fff9754', 'zh', '升级你的数字化工作流或生产力软件订阅。', '古代车辆扩展了人类足迹。现代语境下，提升工作速度的工具就是你的‘交通工具’。');
INSERT INTO omens (id) VALUES ('83368b36-4926-48b6-8da7-00f29e405eee');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('买车', '83368b36-4926-48b6-8da7-00f29e405eee');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('83368b36-4926-48b6-8da7-00f29e405eee', 'en', 'Plan a trip or a new route for your commute.', 'Movement is favored today. Changing your physical path can spark a necessary mental breakthrough.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('83368b36-4926-48b6-8da7-00f29e405eee', 'zh', '规划一次旅行或试着走一条新的通勤路线。', '今日宜动。改变物理路径可以激发必要的思维突破。');
INSERT INTO omens (id) VALUES ('d98838f3-c102-4524-b274-466b43b1c954');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('交易', 'd98838f3-c102-4524-b274-466b43b1c954');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('d98838f3-c102-4524-b274-466b43b1c954', 'en', 'Review your subscriptions and cancel unused ones.', 'Ancient trade was about fair exchange. Stop the ''leak'' of resources to ensure your value flows efficiently.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('d98838f3-c102-4524-b274-466b43b1c954', 'zh', '检查并取消那些不再使用的自动扣款订阅。', '古代交易讲求公平互换。停止资源流失，确保你的价值能够高效流转。');
INSERT INTO omens (id) VALUES ('61cfb063-635b-46bb-946b-21c58c6973d8');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('交易', '61cfb063-635b-46bb-946b-21c58c6973d8');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('61cfb063-635b-46bb-946b-21c58c6973d8', 'en', 'Negotiate a better rate or a new contract.', 'Communication for mutual gain is highly auspicious today. Don''t be afraid to ask for a fairer deal.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('61cfb063-635b-46bb-946b-21c58c6973d8', 'zh', '谈判一个更好的费率或签署一份新合同。', '今日利于互利互惠的沟通。不要害怕提出更公平的交易条件。');
INSERT INTO omens (id) VALUES ('e4c89f4e-339b-4dac-88e2-17548a9ee6db');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('伐木', 'e4c89f4e-339b-4dac-88e2-17548a9ee6db');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('e4c89f4e-339b-4dac-88e2-17548a9ee6db', 'en', 'Delete the apps that are cluttering your focus.', 'Lumbering clears the forest for new growth. Remove digital distractions to let your main project thrive.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('e4c89f4e-339b-4dac-88e2-17548a9ee6db', 'zh', '删掉那些分散你精力的手机应用，清空干扰。', '伐木是为新生长清空空间。移除数字化干扰，让你的核心项目得以蓬勃发展。');
INSERT INTO omens (id) VALUES ('d2c811d1-e9ea-4529-90ac-b1e4b151284b');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('伐木', 'd2c811d1-e9ea-4529-90ac-b1e4b151284b');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('d2c811d1-e9ea-4529-90ac-b1e4b151284b', 'en', 'Prune your ''To-Do'' list of non-essential tasks.', 'You cannot do everything. Cutting away the low-value tasks today empowers the high-value ones.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('d2c811d1-e9ea-4529-90ac-b1e4b151284b', 'zh', '从待办清单中精简掉那些非必要的任务。', '你无法完成所有事。今日砍掉低价值任务，是为了赋予高价值任务更多能量。');
INSERT INTO omens (id) VALUES ('3ed32a4d-084f-4b48-be67-f8ab4bfd96e4');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('会亲友', '3ed32a4d-084f-4b48-be67-f8ab4bfd96e4');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('3ed32a4d-084f-4b48-be67-f8ab4bfd96e4', 'en', 'Reach out to an old colleague for a virtual coffee.', 'Socializing today isn''t just for fun; it''s for resource sharing. A simple talk could unlock a new opportunity.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('3ed32a4d-084f-4b48-be67-f8ab4bfd96e4', 'zh', '主动给老同事发个信息，约一场线上叙旧。', '今日的社交不只是消遣，而是资源共享。简单的交谈可能开启全新的机遇。');
INSERT INTO omens (id) VALUES ('2a3aed0d-aa05-4871-a397-f7d00ccb8743');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('会亲友', '2a3aed0d-aa05-4871-a397-f7d00ccb8743');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('2a3aed0d-aa05-4871-a397-f7d00ccb8743', 'en', 'Collaborate on a creative idea with a friend.', 'Collective intelligence is peaked. Two minds working together today will produce 10x the results.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('2a3aed0d-aa05-4871-a397-f7d00ccb8743', 'zh', '与朋友一起为一个创意想法碰撞火花。', '群体智慧处于巅峰。今日两人合力将产生十倍于独自工作的成果。');
INSERT INTO omens (id) VALUES ('c8da4299-0e20-4d86-8262-fe6b866b201b');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('作梁', 'c8da4299-0e20-4d86-8262-fe6b866b201b');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('c8da4299-0e20-4d86-8262-fe6b866b201b', 'en', 'Take ownership of a difficult task at work today.', 'The beam supports the whole roof. Today, proving you can handle the weight increases your authority.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('c8da4299-0e20-4d86-8262-fe6b866b201b', 'zh', '今天主动承担一项难题，展现你的核心能力。', '梁支撑着整个屋顶。今日证明你能承担重任，将提升你的权威感。');
INSERT INTO omens (id) VALUES ('6abbd431-32c6-48d1-b6df-f0f81dd3d73b');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('作梁', '6abbd431-32c6-48d1-b6df-f0f81dd3d73b');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('6abbd431-32c6-48d1-b6df-f0f81dd3d73b', 'en', 'Strengthen the core architecture of your project.', 'Before adding features, fix the foundation. Today is lucky for deep structural improvements.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('6abbd431-32c6-48d1-b6df-f0f81dd3d73b', 'zh', '加固你项目的基础架构或底层逻辑。', '在增加功能前，先修补基础。今日适合进行深层的架构优化。');
INSERT INTO omens (id) VALUES ('45d64bd1-ce3c-448f-9a0b-a33e078602eb');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('作灶', '45d64bd1-ce3c-448f-9a0b-a33e078602eb');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('45d64bd1-ce3c-448f-9a0b-a33e078602eb', 'en', 'Meal prep for the week or try a healthy recipe.', 'The ''Hearth'' is the energy center of the home. Optimizing your nutrition today fuels your productivity for the week.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('45d64bd1-ce3c-448f-9a0b-a33e078602eb', 'zh', '今天宜下厨，为自己准备一份营养均衡的餐食。', '‘灶’是家庭的能量中心。今日优化营养摄入，能为你一周的生产力补足燃料。');
INSERT INTO omens (id) VALUES ('aa679597-46c6-4bc9-aa60-f8608b0276a1');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('作灶', 'aa679597-46c6-4bc9-aa60-f8608b0276a1');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('aa679597-46c6-4bc9-aa60-f8608b0276a1', 'en', 'Optimize your kitchen or dining environment.', 'A clean energy source leads to a clean mind. Tidying your eating space brings clarity to your work.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('aa679597-46c6-4bc9-aa60-f8608b0276a1', 'zh', '优化你的厨房或用餐环境。', '能量来源清净，思想才会清明。理清用餐环境能让工作思路更清晰。');
INSERT INTO omens (id) VALUES ('0b7b3c4b-5463-4f8c-8961-0540c114aa6b');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('安香', '0b7b3c4b-5463-4f8c-8961-0540c114aa6b');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('0b7b3c4b-5463-4f8c-8961-0540c114aa6b', 'en', 'Create a dedicated ''deep work'' space today.', 'An Xiang is about establishing a sacred space. Setting a physical boundary today tells your brain it''s time to perform.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('0b7b3c4b-5463-4f8c-8961-0540c114aa6b', 'zh', '今日宜设立一个专属的‘深度工作’区。', '古代安香是为了确立神圣空间。今日设定物理边界，能提醒大脑进入高效模式。');
INSERT INTO omens (id) VALUES ('7a5e8072-3031-408c-93f4-91cd8f99f07d');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('安香', '7a5e8072-3031-408c-93f4-91cd8f99f07d');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('7a5e8072-3031-408c-93f4-91cd8f99f07d', 'en', 'Start a 5-minute morning ritual or meditation.', 'This activity invites peace and presence. Setting a new ritual today grounds your mental health.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('7a5e8072-3031-408c-93f4-91cd8f99f07d', 'zh', '开启一项5分钟的早晨仪式或冥想练习。', '此项活动关乎安宁与存在感。今日建立新仪式感，能稳固你的心理健康。');
INSERT INTO omens (id) VALUES ('9d8e0305-ad9d-4917-9da0-f603781bca35');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('掘井', '9d8e0305-ad9d-4917-9da0-f603781bca35');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('9d8e0305-ad9d-4917-9da0-f603781bca35', 'en', 'Dive deep into the documentation or source code.', 'Don''t settle for surface-level answers. Like digging for water, the best insights are found deep in the data today.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('9d8e0305-ad9d-4917-9da0-f603781bca35', 'zh', '深入研究文档或底层源代码。', '不要满足于表面的答案。正如掘井取水，今日最好的洞见藏在数据深处。');
INSERT INTO omens (id) VALUES ('32933f68-4419-433c-99ea-caa1f9b29e88');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('掘井', '32933f68-4419-433c-99ea-caa1f9b29e88');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('32933f68-4419-433c-99ea-caa1f9b29e88', 'en', 'Start a new high-yield savings goal today.', 'A well provides water for years. A financial ''well'' provides security; today is lucky for long-term accumulation.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('32933f68-4419-433c-99ea-caa1f9b29e88', 'zh', '今日宜开启一个长期的理财储蓄计划。', '水井供水多年，财务‘井’提供安全。今日适合开启长期的财富积累。');
INSERT INTO omens (id) VALUES ('24e5c9eb-bf63-45a1-982b-c9cd4e6d447c');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('打猎', '24e5c9eb-bf63-45a1-982b-c9cd4e6d447c');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('24e5c9eb-bf63-45a1-982b-c9cd4e6d447c', 'en', 'Apply for that ''reach'' job or send a cold pitch.', 'Ancient hunting was about skill and survival. Today, your ''predatory'' instincts are sharp—go after a high-value target.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('24e5c9eb-bf63-45a1-982b-c9cd4e6d447c', 'zh', '主动投递简历或向客户发送一份提案。', '古代打猎关乎生存技能。今日你的竞争直觉敏锐，适合主动出击获取高价值机会。');
INSERT INTO omens (id) VALUES ('a3ce8e80-9ab1-443f-8c61-b13f9642d7e9');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('打猎', 'a3ce8e80-9ab1-443f-8c61-b13f9642d7e9');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('a3ce8e80-9ab1-443f-8c61-b13f9642d7e9', 'en', 'Conduct a competitive analysis of your rivals.', 'Know your environment and your ''prey''. Use today to study the market gap and prepare your move.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('a3ce8e80-9ab1-443f-8c61-b13f9642d7e9', 'zh', '对竞争对手进行一次深度分析。', '了解环境与对手。今日宜研究市场空白，为下一步行动做准备。');
INSERT INTO omens (id) VALUES ('8599d6ad-8b51-43a6-9457-610a32cc948e');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('修坟', '8599d6ad-8b51-43a6-9457-610a32cc948e');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('8599d6ad-8b51-43a6-9457-610a32cc948e', 'en', 'Update your digital legacy or emergency contacts.', 'Respecting the past ensures a smooth future. Take a moment to organize the vital info your loved ones might need.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('8599d6ad-8b51-43a6-9457-610a32cc948e', 'zh', '更新你的数字遗产设置或紧急联系人。', '敬畏过去，方能安稳前行。花点时间整理那些至关重要的个人信息与备份。');
INSERT INTO omens (id) VALUES ('4f503c5f-4259-46cd-aa7f-a7bc7a56dc9f');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('修坟', '4f503c5f-4259-46cd-aa7f-a7bc7a56dc9f');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('4f503c5f-4259-46cd-aa7f-a7bc7a56dc9f', 'en', 'Review a past project to fix its lingering issues.', 'Mending a grave is about honor and repair. Fixing old mistakes today prevents them from haunting your current work.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('4f503c5f-4259-46cd-aa7f-a7bc7a56dc9f', 'zh', '回顾过去的项目并修复那些遗留的小问题。', '修葺坟茔意在缅怀与修复。今日修正旧错，能防止过去的失误干扰现有的进程。');
INSERT INTO omens (id) VALUES ('79dfcd12-f583-44e4-8c54-5f75a33c2f05');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('修造', '79dfcd12-f583-44e4-8c54-5f75a33c2f05');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('79dfcd12-f583-44e4-8c54-5f75a33c2f05', 'en', 'Optimize your home office for better ergonomics.', 'Small structural changes lead to big productivity gains. Adjust your monitor or chair to support your growth.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('79dfcd12-f583-44e4-8c54-5f75a33c2f05', 'zh', '优化居家办公的人体工学设置。', '微小的结构调整能带来巨大的产能提升。调整桌椅高度，让环境支撑你的进步。');
INSERT INTO omens (id) VALUES ('ad0b9f8a-aece-4e06-a3b0-0860213b67ee');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('修造', 'ad0b9f8a-aece-4e06-a3b0-0860213b67ee');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('ad0b9f8a-aece-4e06-a3b0-0860213b67ee', 'en', 'Start a renovation or a DIY repair project today.', 'Physical maintenance mirrors mental maintenance. Improving your environment today brings fresh energy into your life.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('ad0b9f8a-aece-4e06-a3b0-0860213b67ee', 'zh', '今天宜开始一项修缮或DIY改造计划。', '物理环境的维护映射着心理状态。改善居住空间，能为生活注入全新的能量。');
INSERT INTO omens (id) VALUES ('1efa40fc-1e9e-4c6e-9f37-3952de3004f4');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('入殓', '1efa40fc-1e9e-4c6e-9f37-3952de3004f4');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('1efa40fc-1e9e-4c6e-9f37-3952de3004f4', 'en', 'Archive an old folder and move it out of sight.', 'Closure is necessary for peace. Formally ''burying'' a finished project clears the mental space for what''s next.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('1efa40fc-1e9e-4c6e-9f37-3952de3004f4', 'zh', '归档一个旧文件夹，将其移出视线范围。', '告别是获得安宁的必要途径。正式‘埋葬’已完成的项目，能为下个目标腾出心力。');
INSERT INTO omens (id) VALUES ('b70e0f29-8d01-4fdb-9716-2ccd0d4df430');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('入殓', 'b70e0f29-8d01-4fdb-9716-2ccd0d4df430');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('b70e0f29-8d01-4fdb-9716-2ccd0d4df430', 'en', 'Finalize a decision you have been avoiding.', 'Accepting an ending is a powerful act of will. Today is lucky for finality and formal acceptance.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('b70e0f29-8d01-4fdb-9716-2ccd0d4df430', 'zh', '为那个你一直在逃避的决定画上句号。', '接纳终结是意志力的体现。今日利于尘埃落定，在心态上完成正式的交接。');
INSERT INTO omens (id) VALUES ('8f71eec0-2a09-4da3-83f6-84ab0b5df8a9');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('出火', '8f71eec0-2a09-4da3-83f6-84ab0b5df8a9');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('8f71eec0-2a09-4da3-83f6-84ab0b5df8a9', 'en', 'Delete toxic contacts or leave draining group chats.', 'Removing the flame prevents the burn. Exit environments that stir up unnecessary heat and friction.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('8f71eec0-2a09-4da3-83f6-84ab0b5df8a9', 'zh', '删除有毒的联系人，退出那些消耗你的群聊。', '移走火源方能避免灼伤。今日宜退出那些引发无谓争端与内耗的环境。');
INSERT INTO omens (id) VALUES ('5ae5a760-4401-417d-9db8-311fe71857f9');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('出火', '5ae5a760-4401-417d-9db8-311fe71857f9');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('5ae5a760-4401-417d-9db8-311fe71857f9', 'en', 'Reset your router and clear your cache for a fresh start.', 'Moving energy requires clearing the channels. A quick tech reset today mirrors the ancient clearing of a space.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('5ae5a760-4401-417d-9db8-311fe71857f9', 'zh', '重启你的路由器并清除缓存，焕然一新。', '能量的流动需要清空渠道。今日的小型设备重启，正合乎古代空间清扫之意。');
INSERT INTO omens (id) VALUES ('2a9e62fd-2580-4b4b-9a10-271f255d4b44');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('出行', '2a9e62fd-2580-4b4b-9a10-271f255d4b44');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('2a9e62fd-2580-4b4b-9a10-271f255d4b44', 'en', 'Take a different route to work; inspiration awaits.', 'Changing your scenery changes your perspective. Today, a small detour could lead to a big breakthrough.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('2a9e62fd-2580-4b4b-9a10-271f255d4b44', 'zh', '换一条通勤路线；灵感就在不经意间。', '风景的改变会带来视角的转变。今日的小小绕路，可能会触发重大的思维突破。');
INSERT INTO omens (id) VALUES ('ef121130-3007-4ae4-b1de-308a58966044');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('出行', 'ef121130-3007-4ae4-b1de-308a58966044');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('ef121130-3007-4ae4-b1de-308a58966044', 'en', 'Book a ticket or plan a trip for your future growth.', 'The universe favors movement today. Travel expands your horizons and brings back new solutions to old problems.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('ef121130-3007-4ae4-b1de-308a58966044', 'zh', '预定机票或为未来的成长规划一场旅行。', '今日宇宙利于移动。远行能开阔眼界，并为老问题带回全新的解决方案。');
INSERT INTO omens (id) VALUES ('0b45def4-f90a-4b8f-8ce6-c16dbd12d26c');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('出货财', '0b45def4-f90a-4b8f-8ce6-c16dbd12d26c');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('0b45def4-f90a-4b8f-8ce6-c16dbd12d26c', 'en', 'Sell an unused item online to clear your space.', 'Stagnant items block stagnant energy. Turning clutter into cash today is highly auspicious.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('0b45def4-f90a-4b8f-8ce6-c16dbd12d26c', 'zh', '在网上卖掉一件闲置物品，清空你的空间。', '停滞的物品会阻塞能量。今日将闲置物转化为现金，是极佳的选择。');
INSERT INTO omens (id) VALUES ('c0ed4c75-585f-4d99-ba76-6803e29d4994');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('出货财', 'c0ed4c75-585f-4d99-ba76-6803e29d4994');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('c0ed4c75-585f-4d99-ba76-6803e29d4994', 'en', 'Make a purposeful purchase that aids your productivity.', 'Money is energy meant to circulate. Spending on tools today creates a return on your investment quickly.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('c0ed4c75-585f-4d99-ba76-6803e29d4994', 'zh', '进行一次有针对性的投资，提升你的生产力。', '金钱是流动的能量。今日在专业工具上的投入，将很快为你带来回报。');
INSERT INTO omens (id) VALUES ('4bd3e97c-3524-4b44-8a34-d50878dc609d');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('分居', '4bd3e97c-3524-4b44-8a34-d50878dc609d');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('4bd3e97c-3524-4b44-8a34-d50878dc609d', 'en', 'Set a firm boundary with a co-worker or friend.', 'Separation is sometimes the path to harmony. Define where you end and others begin to preserve your focus.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('4bd3e97c-3524-4b44-8a34-d50878dc609d', 'zh', '与同事或朋友设定一个明确的界限。', '有时分离是为了更好的和谐。明确自己的边界，能有效保护你的专注力。');
INSERT INTO omens (id) VALUES ('49c23a5f-8c23-43e4-92af-fae539b364a1');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('分居', '49c23a5f-8c23-43e4-92af-fae539b364a1');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('49c23a5f-8c23-43e4-92af-fae539b364a1', 'en', 'Work from a different location to gain independence.', 'Breaking a routine connection forces self-reliance. Today, solitude is your greatest competitive advantage.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('49c23a5f-8c23-43e4-92af-fae539b364a1', 'zh', '换个地方办公，找回那份独立感。', '打破常规的依赖能强迫自我独立。今日，独处是你最强大的竞争优势。');
INSERT INTO omens (id) VALUES ('40578bc6-45f1-4d92-aa4f-63eefba6ae56');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('割蜜', '40578bc6-45f1-4d92-aa4f-63eefba6ae56');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('40578bc6-45f1-4d92-aa4f-63eefba6ae56', 'en', 'Collect on a debt or ask for a long-awaited favor.', 'Harvesting honey is about reaping rewards. Today is the day to collect the ''sweetness'' you have worked for.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('40578bc6-45f1-4d92-aa4f-63eefba6ae56', 'zh', '收回欠款，或请求一个期待已久的帮助。', '割蜜意在收获果实。今日适合去采摘那些你此前辛勤耕耘所积攒的‘甜头’。');
INSERT INTO omens (id) VALUES ('94424095-fa77-4a38-b417-b0507c59bd22');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('割蜜', '94424095-fa77-4a38-b417-b0507c59bd22');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('94424095-fa77-4a38-b417-b0507c59bd22', 'en', 'Review your savings and enjoy the progress you''ve made.', 'Take a moment to acknowledge your abundance. Recognizing your gains encourages more to flow in.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('94424095-fa77-4a38-b417-b0507c59bd22', 'zh', '查看你的储蓄，享受你已经取得的进展。', '花点时间确认你的富足。认可已有的收获，会吸引更多财富流向你。');
INSERT INTO omens (id) VALUES ('d27b79bd-3f4b-4da4-8da8-b7e74aabffdf');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('动土', 'd27b79bd-3f4b-4da4-8da8-b7e74aabffdf');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('d27b79bd-3f4b-4da4-8da8-b7e74aabffdf', 'en', 'Begin the first draft of your most ambitious project.', 'Breaking ground is the start of creation. Don''t worry about perfection; just start the transformation today.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('d27b79bd-3f4b-4da4-8da8-b7e74aabffdf', 'zh', '为那个最有野心的项目写下第一份草稿。', '动土是创造的开端。不要担心不完美，今日只需开启转化的第一步。');
INSERT INTO omens (id) VALUES ('f2f5f9a4-6dc8-477f-b3e0-756a0d01a297');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('动土', 'f2f5f9a4-6dc8-477f-b3e0-756a0d01a297');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('f2f5f9a4-6dc8-477f-b3e0-756a0d01a297', 'en', 'Deep clean a corner of your room you''ve ignored.', 'Disturbing the dust clears the path. A literal or metaphorical deep dive into your ''ground'' brings hidden treasures.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('f2f5f9a4-6dc8-477f-b3e0-756a0d01a297', 'zh', '深度清理房间里那个一直被你忽视的角落。', '惊动尘土方能清空路径。对你的‘地盘’进行深度挖掘，会带来意想不到的收获。');
INSERT INTO omens (id) VALUES ('87a3d077-81b9-4adf-8898-262ada39cc87');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('合婚订婚', '87a3d077-81b9-4adf-8898-262ada39cc87');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('87a3d077-81b9-4adf-8898-262ada39cc87', 'en', 'Commit to a long-term partnership or contract.', 'Auspicious for union and agreement. Today is a strong day to lock in a ''win-win'' collaboration.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('87a3d077-81b9-4adf-8898-262ada39cc87', 'zh', '承诺一份长期的合作伙伴关系或签署合同。', '今日利于结合与协议。这是锁定双赢合作、达成长期契约的吉日。');
INSERT INTO omens (id) VALUES ('86cb2850-bfbf-4945-80bd-d66bd3926427');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('合婚订婚', '86cb2850-bfbf-4945-80bd-d66bd3926427');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('86cb2850-bfbf-4945-80bd-d66bd3926427', 'en', 'Sync your goals with a partner to ensure alignment.', 'Unity is power. Merging your vision with another person today creates an unshakeable foundation for the future.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('86cb2850-bfbf-4945-80bd-d66bd3926427', 'zh', '与伴侣或搭档同步目标，确保步调一致。', '团结就是力量。今日将你的愿景与他人融合，能为未来打下不可撼动的基石。');
INSERT INTO omens (id) VALUES ('46ad67f9-628d-459c-b8fa-3589153e1e3a');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('合寿木', '46ad67f9-628d-459c-b8fa-3589153e1e3a');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('46ad67f9-628d-459c-b8fa-3589153e1e3a', 'en', 'Update your insurance or long-term safety net.', 'Preparing for the inevitable brings peace of mind. Today is auspicious for securing your future ''casing'' and protection.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('46ad67f9-628d-459c-b8fa-3589153e1e3a', 'zh', '更新你的保险计划或长期安全保障。', '未雨绸缪方能心安。今日最宜加固你的未来保障体系，为不可预知的未来做好准备。');
INSERT INTO omens (id) VALUES ('4557b0ef-7a25-4812-9c9b-bf5df9270b6d');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('合寿木', '4557b0ef-7a25-4812-9c9b-bf5df9270b6d');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('4557b0ef-7a25-4812-9c9b-bf5df9270b6d', 'en', 'Invest in high-quality furniture that will last a lifetime.', 'Anciently about preparing a casket; modernly about investing in durable, long-term craftsmanship for your life.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('4557b0ef-7a25-4812-9c9b-bf5df9270b6d', 'zh', '投资一件可以伴随你一生的优质家具。', '古代指制作寿材；现代宜投资那些工艺精良、能经受时间考验的长久之物。');
INSERT INTO omens (id) VALUES ('8835395a-be71-495a-8cd6-38705e6d91d1');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('合脊', '8835395a-be71-495a-8cd6-38705e6d91d1');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('8835395a-be71-495a-8cd6-38705e6d91d1', 'en', 'Finalize the overarching logic of your current project.', 'The ridgepole connects the two sides of a roof. Today is perfect for unifying your separate ideas into one solid strategy.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('8835395a-be71-495a-8cd6-38705e6d91d1', 'zh', '敲定你目前项目的核心底层逻辑。', '屋脊连接屋顶两侧。今日最适合将你零散的想法统一成一个坚实的战略整体。');
INSERT INTO omens (id) VALUES ('c1e1c1a9-ab12-4e51-ac18-e48875949338');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('合脊', 'c1e1c1a9-ab12-4e51-ac18-e48875949338');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('c1e1c1a9-ab12-4e51-ac18-e48875949338', 'en', 'Strengthen your core values or personal boundaries.', 'A strong ridge protects the whole house. Aligning your actions with your ''backbone'' today ensures long-term integrity.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('c1e1c1a9-ab12-4e51-ac18-e48875949338', 'zh', '加固你的核心价值观或个人底线。', '脊梁强韧则全屋稳固。今日宜言行合一，加固你的内在准则，确保长期的正直与稳定。');
INSERT INTO omens (id) VALUES ('1e5f04e4-8dbb-4d35-805a-42ff87510d55');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('合帐', '1e5f04e4-8dbb-4d35-805a-42ff87510d55');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('1e5f04e4-8dbb-4d35-805a-42ff87510d55', 'en', 'Audit your privacy settings and secure your data.', 'Closing the curtains is about privacy. Use today to create a ''digital veil'' around your personal information.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('1e5f04e4-8dbb-4d35-805a-42ff87510d55', 'zh', '审计你的隐私设置，确保数据安全。', '合帐意在保护隐私。今日宜为你的个人信息建立一道‘数字屏障’，确保私密性。');
INSERT INTO omens (id) VALUES ('78ab6022-0b2e-4b10-ada7-c4863bb93215');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('合帐', '78ab6022-0b2e-4b10-ada7-c4863bb93215');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('78ab6022-0b2e-4b10-ada7-c4863bb93215', 'en', 'Set a dedicated ''off-time'' for your devices tonight.', 'Creating a boundary for sleep ensures recovery. Shield your rest from the noise of the outside world today.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('78ab6022-0b2e-4b10-ada7-c4863bb93215', 'zh', '为今晚的电子设备设定一个明确的‘下班时间’。', '为睡眠设定边界方能有效恢复。今日宜屏蔽外界噪音，保护你宝贵的休息时间。');
INSERT INTO omens (id) VALUES ('1e9095c6-21eb-48da-ae50-138512b82f56');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('坏垣', '1e9095c6-21eb-48da-ae50-138512b82f56');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('1e9095c6-21eb-48da-ae50-138512b82f56', 'en', 'Tear down an old system that is no longer working.', 'Breaking down a wall makes room for a better one. Don''t fear the destruction; it is the first step of renovation.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('1e9095c6-21eb-48da-ae50-138512b82f56', 'zh', '拆除一个已经失效的旧系统或旧习惯。', '推倒旧墙是为了筑起新墙。不要畏惧破坏，这是优化升级的第一步。');
INSERT INTO omens (id) VALUES ('a571d3d0-73d5-4db1-833d-5eb2ef3dcdc2');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('坏垣', 'a571d3d0-73d5-4db1-833d-5eb2ef3dcdc2');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('a571d3d0-73d5-4db1-833d-5eb2ef3dcdc2', 'en', 'Unsubscribe from emails that no longer add value.', 'Removing the barriers to your focus is auspicious. Clear out the ''clutter'' that blocks your daily view.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('a571d3d0-73d5-4db1-833d-5eb2ef3dcdc2', 'zh', '退订那些不再为你产生价值的邮件列表。', '清除影响专注的障碍是明智之举。今日宜清理那些阻挡你视野的数字碎片。');
INSERT INTO omens (id) VALUES ('890a8964-ee5f-4e06-a567-083d71259559');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('塑绘', '890a8964-ee5f-4e06-a567-083d71259559');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('890a8964-ee5f-4e06-a567-083d71259559', 'en', 'Update your brand logo or social media profile picture.', 'Sculpting and painting is about defining an image. Today is lucky for refining how you are perceived by others.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('890a8964-ee5f-4e06-a567-083d71259559', 'zh', '更新你的品牌标志或社交媒体头像。', '塑绘意在定义形象。今日利于修饰你的‘对外名片’，完善外界对你的第一印象。');
INSERT INTO omens (id) VALUES ('a3cce846-28bf-4bce-b6f0-f0f3c920cf7b');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('塑绘', 'a3cce846-28bf-4bce-b6f0-f0f3c920cf7b');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('a3cce846-28bf-4bce-b6f0-f0f3c920cf7b', 'en', 'Visualize your goals by creating a vision board.', 'Giving shape to your thoughts makes them real. Use creative visuals today to cement your future intentions.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('a3cce846-28bf-4bce-b6f0-f0f3c920cf7b', 'zh', '通过制作愿景板来可视化你的目标。', '赋予想法形状能让其变为现实。今日宜用视觉化的方式锁定你未来的意图。');
INSERT INTO omens (id) VALUES ('f51e84c4-1167-47bf-a0b6-7a3294352571');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('塞穴', 'f51e84c4-1167-47bf-a0b6-7a3294352571');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('f51e84c4-1167-47bf-a0b6-7a3294352571', 'en', 'Fix the minor bugs or ''leaks'' in your current workflow.', 'Plugging the holes prevents loss. Address the small inefficiencies today before they become big problems.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('f51e84c4-1167-47bf-a0b6-7a3294352571', 'zh', '修复目前工作流中的小漏洞或‘泄压点’。', '堵住漏洞方能防止流失。今日宜解决微小的低效环节，防微杜渐。');
INSERT INTO omens (id) VALUES ('812b7f3a-f43d-4df9-bfa2-985c896ccd7f');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('塞穴', '812b7f3a-f43d-4df9-bfa2-985c896ccd7f');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('812b7f3a-f43d-4df9-bfa2-985c896ccd7f', 'en', 'Finalize your taxes or settle any pending paperwork.', 'Closing open loops brings immense relief. Today is auspicious for ''capping'' tasks that have been draining your energy.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('812b7f3a-f43d-4df9-bfa2-985c896ccd7f', 'zh', '清缴税款或处理任何悬而未决的文件事项。', '闭环能带来巨大的解脱感。今日宜完成那些一直消耗你精力的琐碎任务。');
INSERT INTO omens (id) VALUES ('80b05380-1612-4f4f-a933-1f791d2994c2');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('安床', '80b05380-1612-4f4f-a933-1f791d2994c2');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('80b05380-1612-4f4f-a933-1f791d2994c2', 'en', 'Reset your bedroom environment for optimal rest.', 'A stable bed leads to a stable mind. Today is the best day to prioritize the quality of your recovery.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('80b05380-1612-4f4f-a933-1f791d2994c2', 'zh', '重新整理卧室环境以获得最佳休息体验。', '卧安则神稳。今日是提升睡眠质量、优化恢复环境的最佳时机。');
INSERT INTO omens (id) VALUES ('c507c342-e9c3-4da9-bd01-8c05a207723b');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('安床', 'c507c342-e9c3-4da9-bd01-8c05a207723b');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('c507c342-e9c3-4da9-bd01-8c05a207723b', 'en', 'Commit to a consistent sleep-wake schedule today.', 'Establishing a rhythm is the foundation of health. Lock in your rest patterns to boost your creative energy.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('c507c342-e9c3-4da9-bd01-8c05a207723b', 'zh', '今日起承诺执行一套稳定的睡眠作息表。', '建立节奏是健康的基石。固定你的休息模式，能有效提升你的创造力。');
INSERT INTO omens (id) VALUES ('cf7248a6-d742-4fd9-9193-052279952602');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('安机械', 'cf7248a6-d742-4fd9-9193-052279952602');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('cf7248a6-d742-4fd9-9193-052279952602', 'en', 'Install a new productivity app or hardware tool.', 'Setting up machinery expands your capabilities. Today is favored for integrating technology into your life.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('cf7248a6-d742-4fd9-9193-052279952602', 'zh', '安装一款新的生产力应用或硬件工具。', '安设机械意在扩展能力。今日利于将新技术整合进你的生活与工作。');
INSERT INTO omens (id) VALUES ('0a8e5431-6c2c-4a08-9bac-f21ea6d52b0f');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('安机械', '0a8e5431-6c2c-4a08-9bac-f21ea6d52b0f');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('0a8e5431-6c2c-4a08-9bac-f21ea6d52b0f', 'en', 'Optimize your computer''s performance and startup settings.', 'Ensuring your ''tools'' run smoothly is vital. A quick tech calibration today ensures you move without friction.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('0a8e5431-6c2c-4a08-9bac-f21ea6d52b0f', 'zh', '优化电脑性能并清理开机启动项。', '确保‘工欲善其事’。今日对生产工具进行校准与优化，能让你接下来的行动毫无阻力。');
INSERT INTO omens (id) VALUES ('1c644e65-9a14-4950-9110-7dec97f4add5');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('安葬', '1c644e65-9a14-4950-9110-7dec97f4add5');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('1c644e65-9a14-4950-9110-7dec97f4add5', 'en', 'Fully archive a project and stop thinking about it.', 'Proper burial allows for peaceful rebirth. Formally ending a chapter today lets your focus shift to the new.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('1c644e65-9a14-4950-9110-7dec97f4add5', 'zh', '彻底归档一个项目，不再对其魂牵梦绕。', '妥善的终结方能开启重生。今日正式结束一个篇章，让你的专注力彻底转向新目标。');
INSERT INTO omens (id) VALUES ('3a09f47d-1baf-48b1-843a-532bcd8642ef');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('安葬', '3a09f47d-1baf-48b1-843a-532bcd8642ef');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('3a09f47d-1baf-48b1-843a-532bcd8642ef', 'en', 'Perform a ''digital cleanup'' of old, useless files.', 'Removing the dead weight lightens your load. Clear out the artifacts of the past to speed up your future.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('3a09f47d-1baf-48b1-843a-532bcd8642ef', 'zh', '对陈旧且无用的文件进行一次‘数字大清理’。', '卸下包袱方能轻装上阵。清空过去的遗迹，能大幅提升你通往未来的速度。');
INSERT INTO omens (id) VALUES ('f3702127-ede7-49ff-91d7-9fef0443fcb5');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('安装器具', 'f3702127-ede7-49ff-91d7-9fef0443fcb5');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('f3702127-ede7-49ff-91d7-9fef0443fcb5', 'en', 'Assemble that new piece of furniture or equipment.', 'Bringing tools into their final form is satisfying. Completing the setup today makes your environment work for you.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('f3702127-ede7-49ff-91d7-9fef0443fcb5', 'zh', '组装那件新买的家具或专业设备。', '赋予工具完整的形态。今日完成环境配置，能让空间更好地为你服务。');
INSERT INTO omens (id) VALUES ('fa50e4cd-a633-40b1-83f1-285f9bfc1753');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('安装器具', 'fa50e4cd-a633-40b1-83f1-285f9bfc1753');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('fa50e4cd-a633-40b1-83f1-285f9bfc1753', 'en', 'Set up a new smart-home or automation routine.', 'Automation is the modern ''appliance''. Today is lucky for creating systems that save you time and effort.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('fa50e4cd-a633-40b1-83f1-285f9bfc1753', 'zh', '设置一套新的智能家居或自动化工作流。', '自动化是现代的‘器具’。今日宜建立省时省力的系统，让技术代劳琐事。');
INSERT INTO omens (id) VALUES ('79d8daa6-b49d-4c8a-8c1f-a340999de171');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('安门', '79d8daa6-b49d-4c8a-8c1f-a340999de171');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('79d8daa6-b49d-4c8a-8c1f-a340999de171', 'en', 'Set a new boundary for your personal accessibility.', 'Installing a door controls who enters your space. Today is auspicious for deciding when to be ''open'' and when to be ''closed'' to distractions.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('79d8daa6-b49d-4c8a-8c1f-a340999de171', 'zh', '为你的个人社交触达设定一个新的边界。', '安门意在掌控空间的进出。今日最宜决定何时‘对外开放’，以及何时‘关门’屏蔽干扰。');
INSERT INTO omens (id) VALUES ('6e3b48f9-8b0f-4a9b-a1c2-cb2ca456c12d');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('安门', '6e3b48f9-8b0f-4a9b-a1c2-cb2ca456c12d');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('6e3b48f9-8b0f-4a9b-a1c2-cb2ca456c12d', 'en', 'Update the security and passwords for your main accounts.', 'A strong door is the first line of defense. Strengthening your digital ''gate'' today ensures your assets remain secure.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('6e3b48f9-8b0f-4a9b-a1c2-cb2ca456c12d', 'zh', '更新你主要账号的安全设置与密码。', '坚固的门是第一道防线。今日加固你的数字‘门户’，能确保你的资产万无一失。');
INSERT INTO omens (id) VALUES ('53c2daeb-91f8-4065-9ec7-0b567699e83d');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('安香', '53c2daeb-91f8-4065-9ec7-0b567699e83d');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('53c2daeb-91f8-4065-9ec7-0b567699e83d', 'en', 'Designate a corner of your home specifically for focus.', 'Establishing an altar is about inviting intention. Setting a physical anchor for your ''creative spirit'' today boosts mental clarity.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('53c2daeb-91f8-4065-9ec7-0b567699e83d', 'zh', '在家里指定一个专门用于深度思考的角落。', '安香意在引入意图。今日为你的‘创作精神’设定一个物理锚点，能显著提升思维清晰度。');
INSERT INTO omens (id) VALUES ('aa6293d7-6e0a-4974-ae36-a9f676b1f638');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('安香', 'aa6293d7-6e0a-4974-ae36-a9f676b1f638');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('aa6293d7-6e0a-4974-ae36-a9f676b1f638', 'en', 'Start a short mindfulness or breathing habit today.', 'This is about centering your inner energy. A few minutes of quiet today will stabilize your productivity for the entire week.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('aa6293d7-6e0a-4974-ae36-a9f676b1f638', 'zh', '今天开始一项简短的正念或呼吸练习习惯。', '此项活动关乎内在能量的中心化。今日片刻的宁静，将稳固你一整周的产出效率。');
INSERT INTO omens (id) VALUES ('2eb680db-665f-41e0-aa5b-f6e299a446e4');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('定磉', '2eb680db-665f-41e0-aa5b-f6e299a446e4');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('2eb680db-665f-41e0-aa5b-f6e299a446e4', 'en', 'Verify the core assumptions of your business plan.', 'Setting the foundation stone is critical for weight-bearing. Today is lucky for stress-testing your most basic ideas.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('2eb680db-665f-41e0-aa5b-f6e299a446e4', 'zh', '验证你商业计划中最核心的底层假设。', '定磉是承重的关键。今日利于对你最基础的想法进行‘压力测试’，确保基石稳固。');
INSERT INTO omens (id) VALUES ('7cb823e6-0142-499e-a0f0-54e5d29f7f47');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('定磉', '7cb823e6-0142-499e-a0f0-54e5d29f7f47');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('7cb823e6-0142-499e-a0f0-54e5d29f7f47', 'en', 'Invest in a high-quality base for your tech setup.', 'A stable base prevents long-term tilt. Ensuring your physical or digital ''foundation'' is level today ensures future growth.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('7cb823e6-0142-499e-a0f0-54e5d29f7f47', 'zh', '为你的一整套办公设备投资一个高品质的底座。', '稳固的基座能防止长期的倾斜。今日确保你的物理或数字‘基础’水平，能保障未来的增长。');
INSERT INTO omens (id) VALUES ('a62a912b-7c28-4daa-82a5-2cc11db6631e');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('开业', 'a62a912b-7c28-4daa-82a5-2cc11db6631e');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('a62a912b-7c28-4daa-82a5-2cc11db6631e', 'en', 'Announce your new project to the public today.', 'The energy of ''opening'' is at its peak. Today is the best day to invite outside energy and resources into your work.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('a62a912b-7c28-4daa-82a5-2cc11db6631e', 'zh', '今日宜正式向公众发布你的新项目。', '‘开’的能量正值巅峰。今日是吸引外部能量与资源进入你的事业领域的最佳时机。');
INSERT INTO omens (id) VALUES ('759c3ae8-8f29-4705-a190-bea8c933aa53');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('开业', '759c3ae8-8f29-4705-a190-bea8c933aa53');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('759c3ae8-8f29-4705-a190-bea8c933aa53', 'en', 'Send out your first invoice or launch a sales campaign.', 'The flow of commerce is favored. Opening your ''doors'' to revenue today sets a prosperous tone for the month.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('759c3ae8-8f29-4705-a190-bea8c933aa53', 'zh', '发出你的第一张发票，或启动一场促销活动。', '商业流转受吉星庇佑。今日开启营收之门，能为本月奠定繁荣的基调。');
INSERT INTO omens (id) VALUES ('d059cf9b-4d32-4479-9be4-c96317b7b3a0');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('开仓', 'd059cf9b-4d32-4479-9be4-c96317b7b3a0');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('d059cf9b-4d32-4479-9be4-c96317b7b3a0', 'en', 'Review your inventory and optimize your storage.', 'Opening the granary is about managing wealth. Today is auspicious for organizing your resources to prevent waste.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('d059cf9b-4d32-4479-9be4-c96317b7b3a0', 'zh', '清点你的库存并优化你的仓储空间。', '开仓关乎财富管理。今日最宜整理你的资源储备，通过优化管理来防止浪费。');
INSERT INTO omens (id) VALUES ('b46c3b05-f7c1-492d-b043-d72986753367');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('开仓', 'b46c3b05-f7c1-492d-b043-d72986753367');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('b46c3b05-f7c1-492d-b043-d72986753367', 'en', 'Withdraw funds to invest in a tangible asset.', 'Using your reserves to fuel growth is lucky today. It is a good day to turn ''stored'' value into ''active'' value.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('b46c3b05-f7c1-492d-b043-d72986753367', 'zh', '提取部分资金，用于投资一项实物资产。', '今日宜动用储备来驱动增长。将‘储存’的价值转化为‘活跃’的价值是明智之举。');
INSERT INTO omens (id) VALUES ('97c10ec7-d616-455b-acd0-e94f63627239');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('开光', '97c10ec7-d616-455b-acd0-e94f63627239');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('97c10ec7-d616-455b-acd0-e94f63627239', 'en', 'Go live with a final version of your software or site.', 'Consecration gives a project its ''soul''. Today is perfect for letting your work finally meet its audience.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('97c10ec7-d616-455b-acd0-e94f63627239', 'zh', '将你的软件或网站的最终版本正式上线。', '开光赋予项目‘灵魂’。今日最适合让你的作品正式与受众见面，赋予其生命力。');
INSERT INTO omens (id) VALUES ('981eb484-1f32-4044-9a49-c29660096c03');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('开光', '981eb484-1f32-4044-9a49-c29660096c03');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('981eb484-1f32-4044-9a49-c29660096c03', 'en', 'Take a high-quality professional headshot today.', 'This is about ''opening the eyes'' to the world. A clear, powerful image of yourself today will attract the right eyes.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('981eb484-1f32-4044-9a49-c29660096c03', 'zh', '今天宜拍摄一张高水准的职业形象照。', '此项活动意在向世界‘展示真容’。今日一张清晰、有力的个人形象照能吸引正确的目光。');
INSERT INTO omens (id) VALUES ('ed3cd59d-7f13-4908-bf45-517caedf959d');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('开厕', 'ed3cd59d-7f13-4908-bf45-517caedf959d');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('ed3cd59d-7f13-4908-bf45-517caedf959d', 'en', 'Perform a deep audit of your worst habits.', 'Managing waste is essential for health. Today is auspicious for identifying and flushing out systems that drain your time.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('ed3cd59d-7f13-4908-bf45-517caedf959d', 'zh', '对自己最坏的习惯进行一次深度的‘审计’。', '处理废弃物对健康至关重要。今日利于识别并清除那些长期消耗你时间的无用系统。');
INSERT INTO omens (id) VALUES ('9399a25e-37e0-4bb1-88b2-7b2b2446f5ee');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('开厕', '9399a25e-37e0-4bb1-88b2-7b2b2446f5ee');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('9399a25e-37e0-4bb1-88b2-7b2b2446f5ee', 'en', 'Fix a long-ignored technical debt in your codebase.', 'Clearing out the ''plumbing'' improves performance. Addressing the messiest part of your work today brings long-term relief.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('9399a25e-37e0-4bb1-88b2-7b2b2446f5ee', 'zh', '修复代码库中一个被忽视已久的技术债。', '疏通‘管道’能提升整体性能。今日着手处理工作中最凌乱的部分，能带来长期的轻松感。');
INSERT INTO omens (id) VALUES ('4080c1a7-36e7-4ee2-8b14-aa62e9c59efb');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('开柱眼', '4080c1a7-36e7-4ee2-8b14-aa62e9c59efb');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('4080c1a7-36e7-4ee2-8b14-aa62e9c59efb', 'en', 'Look for the hidden gaps in your current strategy.', 'Preparing the joints is about alignment. Finding where things don''t ''fit'' today prevents a collapse later.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('4080c1a7-36e7-4ee2-8b14-aa62e9c59efb', 'zh', '寻找你现有战略中隐藏的漏洞或缺口。', '开柱眼是为了精准衔接。今日发现那些‘不契合’的地方，能防止日后的架构崩塌。');
INSERT INTO omens (id) VALUES ('61c186e8-c309-4103-8a70-a9d226ceffe0');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('开柱眼', '61c186e8-c309-4103-8a70-a9d226ceffe0');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('61c186e8-c309-4103-8a70-a9d226ceffe0', 'en', 'Schedule a detailed 1-on-1 with a key team member.', 'Precision connection is favored. Opening up the ''slots'' for better communication ensures a stronger team structure.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('61c186e8-c309-4103-8a70-a9d226ceffe0', 'zh', '与团队的关键成员安排一次深入的一对一交流。', '今日利于精准的链接。开启深度沟通的‘接口’，能确保团队结构更加稳固。');
INSERT INTO omens (id) VALUES ('71331b9d-c197-486e-9b82-802691fc42fa');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('开池', '71331b9d-c197-486e-9b82-802691fc42fa');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('71331b9d-c197-486e-9b82-802691fc42fa', 'en', 'Create a new ''collection'' for your creative research.', 'A pond stores life-giving water. Today is lucky for creating a digital reservoir where you can save ideas for later.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('71331b9d-c197-486e-9b82-802691fc42fa', 'zh', '为你的创意调研建立一个新的‘素材库’。', '池塘储备生命之水。今日利于建立数字化的‘灵感水库’，为日后的创作积蓄力量。');
INSERT INTO omens (id) VALUES ('c6fe6fd6-2335-46a2-9999-bdb52c0fbeeb');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('开池', 'c6fe6fd6-2335-46a2-9999-bdb52c0fbeeb');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('c6fe6fd6-2335-46a2-9999-bdb52c0fbeeb', 'en', 'Take a long bath or visit a pool to reset your energy.', 'Immersing in water facilitates emotional release. Today, water-based activities will wash away stagnant stress.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('c6fe6fd6-2335-46a2-9999-bdb52c0fbeeb', 'zh', '通过泡澡或去游泳馆来重置你的内在能量。', '沉浸于水中利于情绪释放。今日与水相关的活动能洗去积压的压力，让能量复原。');
INSERT INTO omens (id) VALUES ('ef3e3ec5-3be6-4f7a-9b84-0d00b49b4b24');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('开渠', 'ef3e3ec5-3be6-4f7a-9b84-0d00b49b4b24');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('ef3e3ec5-3be6-4f7a-9b84-0d00b49b4b24', 'en', 'Automate a repetitive task to speed up your workflow.', 'Opening a channel directs the flow. Today is auspicious for creating paths that move information automatically.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('ef3e3ec5-3be6-4f7a-9b84-0d00b49b4b24', 'zh', '通过自动化处理一项重复性任务，提速工作流。', '开渠意在引导流动。今日最利于建立自动化的信息通道，让效率自然流转。');
INSERT INTO omens (id) VALUES ('394aed96-9551-4624-ae92-74a42a147be4');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('开渠', '394aed96-9551-4624-ae92-74a42a147be4');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('394aed96-9551-4624-ae92-74a42a147be4', 'en', 'Clear the path for a stuck payment or project.', 'Removing the blockage allows the current to return. Use today to identify the one thing stopping the flow and remove it.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('394aed96-9551-4624-ae92-74a42a147be4', 'zh', '为一个停滞不前的项目或款项扫清障碍。', '移除障碍方能让水流回归。今日宜找出那个阻碍进展的单一因素，并果断解决它。');
INSERT INTO omens (id) VALUES ('403faf8f-fa6c-4cdd-a7d3-76b82a0293b9');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('开生坟', '403faf8f-fa6c-4cdd-a7d3-76b82a0293b9');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('403faf8f-fa6c-4cdd-a7d3-76b82a0293b9', 'en', 'Draft a ''five-year plan'' for your personal growth.', 'Anciently about preparing a future resting place while alive. Modernly, it is a day for far-sighted planning that secures your future legacy.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('403faf8f-fa6c-4cdd-a7d3-76b82a0293b9', 'zh', '为你的个人成长起草一份‘五年计划’。', '古代指生前营建寿域。在现代，这是进行远景规划、锁定未来个人成就的吉日。');
INSERT INTO omens (id) VALUES ('fb70ef7d-b56a-4bfc-b7c4-5654d39c8688');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('开生坟', 'fb70ef7d-b56a-4bfc-b7c4-5654d39c8688');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('fb70ef7d-b56a-4bfc-b7c4-5654d39c8688', 'en', 'Invest in a long-term retirement or pension fund.', 'Providing for the distant future brings peace to the present. Today is lucky for financial moves that benefit the ''future you''.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('fb70ef7d-b56a-4bfc-b7c4-5654d39c8688', 'zh', '投资一份长期的退休金或养老基金。', '为遥远的未来做准备能带来当下的安宁。今日利于那些能让‘未来的你’受益的财务决策。');
INSERT INTO omens (id) VALUES ('b6ba4b16-0a72-4d48-814b-01b3369365a8');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('归宁', 'b6ba4b16-0a72-4d48-814b-01b3369365a8');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('b6ba4b16-0a72-4d48-814b-01b3369365a8', 'en', 'Reconnect with your roots or visit your hometown.', 'Returning home refreshes the spirit. Today, connecting with your origins provides the emotional fuel needed for your next journey.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('b6ba4b16-0a72-4d48-814b-01b3369365a8', 'zh', '回归本源，或者回一趟老家。', '归宁是精神的充电。今日与本源建立联系，能为你下一段征程提供必要的情感燃料。');
INSERT INTO omens (id) VALUES ('8c030c07-22ca-43ef-8070-9ae5a0fded38');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('归宁', '8c030c07-22ca-43ef-8070-9ae5a0fded38');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('8c030c07-22ca-43ef-8070-9ae5a0fded38', 'en', 'Call a family member to share your recent progress.', 'Maintaining foundational ties strengthens your resolve. A simple conversation with your support system today brings immense clarity.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('8c030c07-22ca-43ef-8070-9ae5a0fded38', 'zh', '给家里人打个电话，分享你最近的进展。', '维持根基性的联系能坚定你的意志。今日与支持你的人进行简单的交流，能带来极大的思维清晰度。');
INSERT INTO omens (id) VALUES ('112d535c-dce5-44ee-9c92-d6caabc840be');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('归岫', '112d535c-dce5-44ee-9c92-d6caabc840be');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('112d535c-dce5-44ee-9c92-d6caabc840be', 'en', 'Retreat from social media for a deep mental reset.', 'Like clouds returning to the cave, today is for heading inward. Silence the noise to hear your own inner voice.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('112d535c-dce5-44ee-9c92-d6caabc840be', 'zh', '从社交媒体中抽身，进行一次深度的精神重置。', '如云归山岫，今日宜向内求索。屏除外界噪音，方能听见内心最真实的渴望。');
INSERT INTO omens (id) VALUES ('8f3864d0-2a5f-44c2-b37e-aee72ffc4c59');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('归岫', '8f3864d0-2a5f-44c2-b37e-aee72ffc4c59');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('8f3864d0-2a5f-44c2-b37e-aee72ffc4c59', 'en', 'End a period of travel and focus on home life.', 'Returning to your ''nest'' is favored. Stability after movement allows you to integrate the lessons you''ve learned on the road.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('8f3864d0-2a5f-44c2-b37e-aee72ffc4c59', 'zh', '结束一段时间的奔波，将重心转回家庭生活。', '归巢之举倍受庇佑。动之后的静，能让你更好地消化并吸收在旅途中学到的见闻。');
INSERT INTO omens (id) VALUES ('333f8e7f-2fd4-41f4-825a-78f9718f5d7f');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('成人礼', '333f8e7f-2fd4-41f4-825a-78f9718f5d7f');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('333f8e7f-2fd4-41f4-825a-78f9718f5d7f', 'en', 'Take full responsibility for a recent mistake.', 'Coming of age is about accountability. Today, owning your actions upgrades your professional status in the eyes of others.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('333f8e7f-2fd4-41f4-825a-78f9718f5d7f', 'zh', '为最近的一个错误承担起全部责任。', '成人的核心是担当。今日承担责任的举动，将显著提升你在他人眼中的职业成熟度。');
INSERT INTO omens (id) VALUES ('c6920aec-9dab-465e-85bd-50023ed24db4');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('成人礼', 'c6920aec-9dab-465e-85bd-50023ed24db4');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('c6920aec-9dab-465e-85bd-50023ed24db4', 'en', 'Complete a task that marks your transition to a new level.', 'Auspicious for ''stepping up''. Finish that difficult certification or project that proves you have entered the next league.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('c6920aec-9dab-465e-85bd-50023ed24db4', 'zh', '完成一项标志着你迈向新台阶的任务。', '今日利于‘晋级’。完成那项艰巨的认证或项目，以此证明你已进入了更高阶的圈层。');
INSERT INTO omens (id) VALUES ('84fa4f9a-9888-4649-95ce-958dc90d98d6');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('成服', '84fa4f9a-9888-4649-95ce-958dc90d98d6');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('84fa4f9a-9888-4649-95ce-958dc90d98d6', 'en', 'Formally accept a major change in your life.', 'Accepting a transition allows you to process it. Today is a day for mental fortitude and facing reality with grace.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('84fa4f9a-9888-4649-95ce-958dc90d98d6', 'zh', '正式接纳生活中发生的一项重大改变。', '接纳变迁方能消化变迁。今日宜展现心理韧性，以优雅的姿态直面现实的转折。');
INSERT INTO omens (id) VALUES ('4ff9713b-ae9c-415a-8a78-212b7cb2ba98');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('成服', '4ff9713b-ae9c-415a-8a78-212b7cb2ba98');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('4ff9713b-ae9c-415a-8a78-212b7cb2ba98', 'en', 'Commit to a period of discipline or focused study.', 'Putting on the ''uniform'' signifies a shift in state. Today is lucky for adopting a stricter routine for a specific goal.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('4ff9713b-ae9c-415a-8a78-212b7cb2ba98', 'zh', '开启一段自律期或专注的学习期。', '披上‘战袍’意味着状态的转变。今日宜针对特定目标，开启一套更为严格的日常作息。');
INSERT INTO omens (id) VALUES ('258d8552-b77e-4dfb-870c-277cbda535c2');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('房屋清洁', '258d8552-b77e-4dfb-870c-277cbda535c2');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('258d8552-b77e-4dfb-870c-277cbda535c2', 'en', 'Organize your desktop and physical workspace.', 'External order reflects internal order. Clearing the dust from your environment today sharpens your decision-making.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('258d8552-b77e-4dfb-870c-277cbda535c2', 'zh', '整理你的电脑桌面和实体办公空间。', '外在的秩序映射内在的条理。今日清空环境中的尘埃，能让你的决策力更加敏锐。');
INSERT INTO omens (id) VALUES ('c693fe56-4224-499f-a21a-a979a0228dc6');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('房屋清洁', 'c693fe56-4224-499f-a21a-a979a0228dc6');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('c693fe56-4224-499f-a21a-a979a0228dc6', 'en', 'Perform a deep digital cleanup of your inbox.', 'Clearing out the old creates space for the new. An organized system today ensures no opportunity is missed tomorrow.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('c693fe56-4224-499f-a21a-a979a0228dc6', 'zh', '对你的电子邮箱进行一次深度的数字大扫除。', '清理旧物方能为新物腾位。今日优化的系统，能确保你明天不会错过任何机会。');
INSERT INTO omens (id) VALUES ('e92006e6-9e91-48f7-9fae-a0578d69feb1');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('打扫', 'e92006e6-9e91-48f7-9fae-a0578d69feb1');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('e92006e6-9e91-48f7-9fae-a0578d69feb1', 'en', 'Sweep away the minor distractions from your day.', 'Daily cleaning prevents buildup. Use today to handle the small, nagging tasks that are clouding your focus.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('e92006e6-9e91-48f7-9fae-a0578d69feb1', 'zh', '扫除今天那些分散你注意力的琐碎小事。', '日常清扫能防患于未然。今日宜处理那些消耗精力的琐碎小事，换取片刻的专注。');
INSERT INTO omens (id) VALUES ('291a1fd6-9a2a-4e1c-99ec-5b677c64f586');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('打扫', '291a1fd6-9a2a-4e1c-99ec-5b677c64f586');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('291a1fd6-9a2a-4e1c-99ec-5b677c64f586', 'en', 'Donate or recycle items that no longer serve you.', 'Letting go of clutter invites abundance. Today is auspicious for removing things that have outlived their purpose.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('291a1fd6-9a2a-4e1c-99ec-5b677c64f586', 'zh', '捐赠或回收那些不再为你产生价值的物品。', '断舍离能引来富足。今日最宜移除那些使命已达、不再被需要的陈旧之物。');
INSERT INTO omens (id) VALUES ('0d01d194-e8c6-4de2-9b63-2ffb9d22204d');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('打猎', '0d01d194-e8c6-4de2-9b63-2ffb9d22204d');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('0d01d194-e8c6-4de2-9b63-2ffb9d22204d', 'en', 'Target a high-value client or a competitive role.', 'Your strategic instincts are sharp today. Focus your energy on a single, difficult goal and pursue it with precision.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('0d01d194-e8c6-4de2-9b63-2ffb9d22204d', 'zh', '锁定一个高价值客户或一个极具竞争力的职位。', '今日你的战略本能异常敏锐。集中精力攻克一个单一的、高难度的目标，精准出击。');
INSERT INTO omens (id) VALUES ('a48d247c-0b3f-4a5b-bcd2-5290a5f55309');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('打猎', 'a48d247c-0b3f-4a5b-bcd2-5290a5f55309');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('a48d247c-0b3f-4a5b-bcd2-5290a5f55309', 'en', 'Go on a ''scouting mission'' for new market trends.', 'Information gathering is favored. Today is about finding where the ''prey'' (opportunities) are before moving in.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('a48d247c-0b3f-4a5b-bcd2-5290a5f55309', 'zh', '为探索新的市场趋势进行一次‘侦察任务’。', '今日利于搜集情报。在采取行动前，先摸清‘猎物’（机遇）所在的方位与动向。');
INSERT INTO omens (id) VALUES ('5107c500-1447-4ea0-8561-f5dd387f02bc');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('打鱼', '5107c500-1447-4ea0-8561-f5dd387f02bc');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('5107c500-1447-4ea0-8561-f5dd387f02bc', 'en', 'Launch a wide-reaching lead generation campaign.', 'Casting a net is about volume and patience. Today is auspicious for activities that bring in a high quantity of new leads.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('5107c500-1447-4ea0-8561-f5dd387f02bc', 'zh', '启动一场覆盖范围广泛的线索获取活动。', '撒网讲求广度与耐心。今日利于那些能为你带回大量潜在客户或新线索的活动。');
INSERT INTO omens (id) VALUES ('48d9d25c-14b8-4d1f-9077-5b9d48ef0790');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('打鱼', '48d9d25c-14b8-4d1f-9077-5b9d48ef0790');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('48d9d25c-14b8-4d1f-9077-5b9d48ef0790', 'en', 'Scroll through forums to find new customer pain points.', 'Gathering insights from the ''pool'' of public opinion is favored. Use today to listen to what the market is asking for.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('48d9d25c-14b8-4d1f-9077-5b9d48ef0790', 'zh', '浏览各大论坛，寻找客户的新痛点。', '从大众舆论的‘池塘’中获取洞见受吉星庇佑。今日宜倾听市场最真实的需求声音。');
INSERT INTO omens (id) VALUES ('57821e60-e0a5-4c83-9798-33bfbc2c0eb2');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('拆卸', '57821e60-e0a5-4c83-9798-33bfbc2c0eb2');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('57821e60-e0a5-4c83-9798-33bfbc2c0eb2', 'en', 'Deconstruct a complex problem into smaller parts.', 'To build something better, you must understand its components. Today is lucky for taking things apart to find a better way.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('57821e60-e0a5-4c83-9798-33bfbc2c0eb2', 'zh', '将一个复杂的问题拆解成更小的、可操作的部分。', '欲善其事，必先解其构。今日利于拆解现状，从内部结构中寻找更优的路径。');
INSERT INTO omens (id) VALUES ('09fd7974-1f8f-44af-88f0-ce2da076ca4c');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('拆卸', '09fd7974-1f8f-44af-88f0-ce2da076ca4c');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('09fd7974-1f8f-44af-88f0-ce2da076ca4c', 'en', 'Dismantle an old project and reuse its best pieces.', 'Resourcefulness is favored today. Don''t waste the ''parts'' of the past; integrate them into your future build.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('09fd7974-1f8f-44af-88f0-ce2da076ca4c', 'zh', '拆除一个旧项目，并回收利用其中最精华的部分。', '今日利于资源的灵活性运用。不要浪费过去的精华，将其整合进你未来的蓝图中。');
INSERT INTO omens (id) VALUES ('b4db9633-6831-4dcc-8866-aae19424a9ef');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('挂匾', 'b4db9633-6831-4dcc-8866-aae19424a9ef');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('b4db9633-6831-4dcc-8866-aae19424a9ef', 'en', 'Publicly announce your new title or brand name today.', 'Hanging a plaque is about public recognition. Today is auspicious for solidifying your identity in the eyes of the world.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('b4db9633-6831-4dcc-8866-aae19424a9ef', 'zh', '今日宜正式公布你的新头衔或品牌名称。', '挂匾象征着公众认可。今日最宜向外界确立你的身份，提升品牌或个人的社会地位。');
INSERT INTO omens (id) VALUES ('b5469adb-51c3-4e37-995f-574a3f82ab64');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('挂匾', 'b5469adb-51c3-4e37-995f-574a3f82ab64');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('b5469adb-51c3-4e37-995f-574a3f82ab64', 'en', 'Add your most impressive achievement to your bio.', 'Displaying excellence attracts opportunity. Use today to showcase your ''prestige'' to potential collaborators.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('b5469adb-51c3-4e37-995f-574a3f82ab64', 'zh', '将你最引以为傲的成就更新在个人简介中。', '展示卓越方能吸引机遇。今日宜公开你的‘高光时刻’，以此赢得合作伙伴的青睐。');
INSERT INTO omens (id) VALUES ('191740c2-1b7e-4147-9a5c-962e2b4279b8');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('掘井', '191740c2-1b7e-4147-9a5c-962e2b4279b8');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('191740c2-1b7e-4147-9a5c-962e2b4279b8', 'en', 'Investigate a new primary source of information.', 'A well provides long-term sustenance. Today is lucky for establishing a ''well'' of knowledge that will feed your career for years.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('191740c2-1b7e-4147-9a5c-962e2b4279b8', 'zh', '去挖掘一个新的、第一手的信息来源。', '井水长流，受用不尽。今日利于建立一个知识库，为你的职业生涯提供长期的养分。');
INSERT INTO omens (id) VALUES ('58800e08-34ed-4ab8-8430-6d55cb7c0e86');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('掘井', '58800e08-34ed-4ab8-8430-6d55cb7c0e86');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('58800e08-34ed-4ab8-8430-6d55cb7c0e86', 'en', 'Automate your recurring savings or investments.', 'Creating a ''flow'' of wealth ensures security. Today is favored for setting up systems that gather resources quietly in the background.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('58800e08-34ed-4ab8-8430-6d55cb7c0e86', 'zh', '为你的定期储蓄或投资设置自动化流转。', '建立财富流向方能确保安全。今日宜设置那些能默默为你积攒资源的自动化系统。');
INSERT INTO omens (id) VALUES ('fb90faf0-d4c2-46a4-97f6-b0af6c17f13f');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('搬家', 'fb90faf0-d4c2-46a4-97f6-b0af6c17f13f');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('fb90faf0-d4c2-46a4-97f6-b0af6c17f13f', 'en', 'Rearrange your furniture to shift the room''s energy.', 'A change of environment sparks a change of mind. Moving your physical position today breaks a mental stalemate.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('fb90faf0-d4c2-46a4-97f6-b0af6c17f13f', 'zh', '重新布置家具位置，置换空间能量。', '环境的迁徙能带动思维的转化。今日改变物理位置，能有效打破心理上的僵局。');
INSERT INTO omens (id) VALUES ('cb681874-b5a6-4676-a1e5-a425ff260a47');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('搬家', 'cb681874-b5a6-4676-a1e5-a425ff260a47');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('cb681874-b5a6-4676-a1e5-a425ff260a47', 'en', 'Start working from a new cafe or co-working space.', 'The universe favors movement and new perspectives. A fresh backdrop today will lead to a fresh set of ideas.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('cb681874-b5a6-4676-a1e5-a425ff260a47', 'zh', '尝试去一家新的咖啡馆或共享空间办公。', '宇宙今日利于迁徙与新视角。身处全新的背景板下，能激发出一整套全新的创意。');
INSERT INTO omens (id) VALUES ('8706c3e0-ee17-4e31-9c61-dda81df87c10');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('搬新房', '8706c3e0-ee17-4e31-9c61-dda81df87c10');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('8706c3e0-ee17-4e31-9c61-dda81df87c10', 'en', 'Launch a project on a brand new platform.', 'Moving into a new home is a total reset. Today is powerful for migrating your work to a superior system or community.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('8706c3e0-ee17-4e31-9c61-dda81df87c10', 'zh', '在一个全新的平台上启动你的项目。', '迁入新居是彻底的重置。今日最利于将你的工作迁移到更先进的系统或圈层中。');
INSERT INTO omens (id) VALUES ('d63bf8bf-979d-43a7-a567-e2f4bb9e0451');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('搬新房', 'd63bf8bf-979d-43a7-a567-e2f4bb9e0451');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('d63bf8bf-979d-43a7-a567-e2f4bb9e0451', 'en', 'Deep clean and ''consecrate'' your new workspace.', 'Establishing a new base requires fresh energy. Clear the air in your new ''home'' today to ensure long-term prosperity.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('d63bf8bf-979d-43a7-a567-e2f4bb9e0451', 'zh', '深度清扫并‘赋予’你新办公区一种仪式感。', '建立新基地需要新鲜能量。今日宜净化新空间的氛围，以此确保长期的兴旺。');
INSERT INTO omens (id) VALUES ('2123826b-d998-4a2d-a4f5-bf4153a6c4c4');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('收养子女', '2123826b-d998-4a2d-a4f5-bf4153a6c4c4');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('2123826b-d998-4a2d-a4f5-bf4153a6c4c4', 'en', 'Onboard a new mentee or hire a promising intern.', 'Adoption is about expanding your circle with intention. Today is lucky for taking someone under your wing for future growth.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('2123826b-d998-4a2d-a4f5-bf4153a6c4c4', 'zh', '开始带一名新徒弟，或入职一位有潜力的实习生。', '收养是带着意图扩展圈层。今日利于提携后辈，通过悉心指导为未来种下善果。');
INSERT INTO omens (id) VALUES ('5aa559df-9a0f-49d7-a9f6-2a04e10df212');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('收养子女', '5aa559df-9a0f-49d7-a9f6-2a04e10df212');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('5aa559df-9a0f-49d7-a9f6-2a04e10df212', 'en', 'Adopt a new creative ''pet project'' that needs care.', 'Nurturing something small leads to big joy. Use today to commit to a project that brings out your protective and creative instincts.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('5aa559df-9a0f-49d7-a9f6-2a04e10df212', 'zh', '开启一个需要悉心呵护的全新‘趣味项目’。', '滋养微小事物能带来巨大愉悦。今日宜开启一个让你充满保护欲与创作欲的新尝试。');
INSERT INTO omens (id) VALUES ('b9da09dd-05bc-40fe-bd76-99ddde2780af');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('放水', 'b9da09dd-05bc-40fe-bd76-99ddde2780af');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('b9da09dd-05bc-40fe-bd76-99ddde2780af', 'en', 'Finalize a large payment or release a budget.', 'Releasing water is about directing flow. Today is auspicious for letting resources out so that they can do their work in the world.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('b9da09dd-05bc-40fe-bd76-99ddde2780af', 'zh', '结算一笔大额款项，或批准一项预算。', '放水意在引导流向。今日最宜释放资源，让资金或能量流向它该去的地方发挥价值。');
INSERT INTO omens (id) VALUES ('63be6541-0daa-4848-b9a0-bac9fea7c138');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('放水', '63be6541-0daa-4848-b9a0-bac9fea7c138');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('63be6541-0daa-4848-b9a0-bac9fea7c138', 'en', 'Share your expertise for free in a public forum.', 'Generosity is the best way to move energy. Today, ''letting your knowledge flow'' will eventually return to you as prestige.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('63be6541-0daa-4848-b9a0-bac9fea7c138', 'zh', '在公开论坛上免费分享你的专业见解。', '慷慨是驱动能量的最佳方式。今日宜‘倾囊相授’，这份知识的流动终会化为声望回归。');
INSERT INTO omens (id) VALUES ('3adbfbe4-b3a9-4c4e-bfa4-f0905fba5ebb');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('教牛马', '3adbfbe4-b3a9-4c4e-bfa4-f0905fba5ebb');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('3adbfbe4-b3a9-4c4e-bfa4-f0905fba5ebb', 'en', 'Update your team''s standard operating procedures.', 'Training animals was about optimizing productivity. Today, training your ''systems'' ensures you get the most out of your hours.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('3adbfbe4-b3a9-4c4e-bfa4-f0905fba5ebb', 'zh', '更新你团队的标准作业程序（SOP）。', '驯养牧畜是为了优化产能。今日宜‘驯化’你的工作系统，确保每一分钟都能产出最大价值。');
INSERT INTO omens (id) VALUES ('15781427-b680-46f3-bc42-4c528950d021');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('教牛马', '15781427-b680-46f3-bc42-4c528950d021');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('15781427-b680-46f3-bc42-4c528950d021', 'en', 'Learn a shortcut or a new set of keyboard commands.', 'Mastering your tools is a form of ''training''. Today is lucky for sharpening your interface with the machines you use daily.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('15781427-b680-46f3-bc42-4c528950d021', 'zh', '学习一个新的快捷键组合或指令集。', '精通工具也是一种‘驯服’。今日利于磨练你与生产工具之间的默契，提升操作流程度。');
INSERT INTO omens (id) VALUES ('5f8aee29-55a5-4aa7-bfbc-c2cdf9561e9d');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('斋醮', '5f8aee29-55a5-4aa7-bfbc-c2cdf9561e9d');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('5f8aee29-55a5-4aa7-bfbc-c2cdf9561e9d', 'en', 'Schedule a total digital detox for the evening.', 'Ritual cleansing purifies the spirit. Today is auspicious for a period of mental ''fasting'' from information and noise.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('5f8aee29-55a5-4aa7-bfbc-c2cdf9561e9d', 'zh', '为今晚安排一次彻底的‘数字斋戒’。', '斋醮意在净化精神。今日利于进行一段时间的信息‘斋戒’，屏除杂念以清空大脑。');
INSERT INTO omens (id) VALUES ('c709dde9-e7a2-4ecc-92f6-0422d8b45775');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('斋醮', 'c709dde9-e7a2-4ecc-92f6-0422d8b45775');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('c709dde9-e7a2-4ecc-92f6-0422d8b45775', 'en', 'Reflect on your values and align your work accordingly.', 'Connecting with the higher purpose brings peace. Today is a strong day for prayer, meditation, or philosophical deep-dives.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('c709dde9-e7a2-4ecc-92f6-0422d8b45775', 'zh', '反思你的价值观，并据此调整你的工作方向。', '连接更高远的使命能带来安宁。今日适合祈祷、冥想或进行深度的哲学思考。');
INSERT INTO omens (id) VALUES ('d0802a7a-e1ca-4ab0-b5c4-912dbdd0c1c8');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('断蚁', 'd0802a7a-e1ca-4ab0-b5c4-912dbdd0c1c8');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('d0802a7a-e1ca-4ab0-b5c4-912dbdd0c1c8', 'en', 'Unsubscribe from the bottom 10% of your notifications.', 'Eliminating ants prevents a future infestation. Today is for cutting off the small, persistent ''pests'' that drain your focus.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('d0802a7a-e1ca-4ab0-b5c4-912dbdd0c1c8', 'zh', '退订那些最没用的最后 10% 的通知提醒。', '断蚁意在杜绝后患。今日宜切断那些细小但持久、不断蚕食你专注力的‘信息干扰’。');
INSERT INTO omens (id) VALUES ('811fd097-b25f-4493-9f3d-e4c3e1eb6e75');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('断蚁', '811fd097-b25f-4493-9f3d-e4c3e1eb6e75');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('811fd097-b25f-4493-9f3d-e4c3e1eb6e75', 'en', 'Identify and block a minor leak in your monthly budget.', 'Tiny leaks can sink big ships. Stopping a small, recurring expense today ensures your long-term wealth stays intact.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('811fd097-b25f-4493-9f3d-e4c3e1eb6e75', 'zh', '识别并堵住每月预算中一个小额的‘出血点’。', '千里之堤毁于蚁穴。今日堵住一个细小的经常性开支，能确保你的长期财富不受侵蚀。');
INSERT INTO omens (id) VALUES ('71d8d123-b9b5-4bf9-8405-dc807e7f0904');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('普渡', '71d8d123-b9b5-4bf9-8405-dc807e7f0904');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('71d8d123-b9b5-4bf9-8405-dc807e7f0904', 'en', 'Donate to a cause or help a stranger without expecting a return.', 'Universal salvation is about balancing the collective energy. A selfless act today clears your own path of hidden obstacles.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('71d8d123-b9b5-4bf9-8405-dc807e7f0904', 'zh', '今日宜随缘布施，或不求回报地帮助一名陌生人。', '普渡意在平衡集体能量。今日的一份无私善举，能为你未来的道路扫清隐形障碍。');
INSERT INTO omens (id) VALUES ('f215ff74-d7bc-4314-a62c-f9b2d0eb44d0');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('普渡', 'f215ff74-d7bc-4314-a62c-f9b2d0eb44d0');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('f215ff74-d7bc-4314-a62c-f9b2d0eb44d0', 'en', 'Offer a word of encouragement to someone struggling online.', 'Compassion is a high-vibration frequency. Sharing your ''light'' today attracts positive synchronicity back into your life.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('f215ff74-d7bc-4314-a62c-f9b2d0eb44d0', 'zh', '给正在经历困难的网友留下一句鼓励的话。', '慈悲是一种高频能量。今日分享你的光芒，会为你吸引正面的人事物回流。');
INSERT INTO omens (id) VALUES ('b42283f2-50fb-4a6b-a94d-15f6fa4f46df');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('架马', 'b42283f2-50fb-4a6b-a94d-15f6fa4f46df');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('b42283f2-50fb-4a6b-a94d-15f6fa4f46df', 'en', 'Set up a temporary pilot program for your new idea.', 'Building a scaffold is about supporting growth. Today is lucky for creating a ''test frame'' before you commit to the final build.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('b42283f2-50fb-4a6b-a94d-15f6fa4f46df', 'zh', '为你的新想法搭建一个临时的‘试点项目’。', '架马是为了给成长提供支撑。今日宜搭建一个测试框架，在正式投入前先验证可行性。');
INSERT INTO omens (id) VALUES ('e2c7e968-0d10-4748-a910-54bb249dc902');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('架马', 'e2c7e968-0d10-4748-a910-54bb249dc902');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('e2c7e968-0d10-4748-a910-54bb249dc902', 'en', 'Collaborate with a specialist to bridge a technical gap.', 'Support structures make the impossible possible. Use today to lean on someone else''s expertise to reach a higher level.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('e2c7e968-0d10-4748-a910-54bb249dc902', 'zh', '与专业人士协作，填补你技术上的短板。', '支撑结构让不可能变为可能。今日宜借助他人的专长，助你跃上更高的台阶。');
INSERT INTO omens (id) VALUES ('e3eb68f5-46f8-49b9-ad03-ec7757b65478');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('栽种', 'e3eb68f5-46f8-49b9-ad03-ec7757b65478');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('e3eb68f5-46f8-49b9-ad03-ec7757b65478', 'en', 'Start a new project that will take months to mature.', 'Planting is an act of faith in the future. Today is the best day to sow a seed that requires patience but yields massive fruit.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('e3eb68f5-46f8-49b9-ad03-ec7757b65478', 'zh', '启动一个需要数月时间才能成熟的新项目。', '栽种是对未来的信任。今日最宜播下一颗需要耐心呵护、但回报丰厚的‘长期种子’。');
INSERT INTO omens (id) VALUES ('ae4cfa36-5f30-4e66-a4d0-c67a53da06ab');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('栽种', 'ae4cfa36-5f30-4e66-a4d0-c67a53da06ab');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('ae4cfa36-5f30-4e66-a4d0-c67a53da06ab', 'en', 'Buy a plant for your desk to improve your air and mood.', 'Nurturing life brings life back to you. Adding a living element to your workspace today boosts your creative vitality.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('ae4cfa36-5f30-4e66-a4d0-c67a53da06ab', 'zh', '为办公桌买一盆绿植，改善空气与心情。', '滋养生命，生命亦会回馈于你。今日为办公空间增添生机，能显著提升创作活力。');
INSERT INTO omens (id) VALUES ('af320164-19a2-491c-a308-4c0031d4e689');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('求医', 'af320164-19a2-491c-a308-4c0031d4e689');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('af320164-19a2-491c-a308-4c0031d4e689', 'en', 'Book a long-overdue checkup or physical therapy session.', 'The universe favors proactive healing today. Addressing a small discomfort now prevents a major breakdown later.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('af320164-19a2-491c-a308-4c0031d4e689', 'zh', '预约一次拖延已久的体检或理疗项目。', '今日宇宙利于主动疗愈。现在着手处理那些细小的不适，能预防日后的大麻烦。');
INSERT INTO omens (id) VALUES ('bd85e32e-1631-4220-be6f-521de5519ea8');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('求医', 'bd85e32e-1631-4220-be6f-521de5519ea8');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('bd85e32e-1631-4220-be6f-521de5519ea8', 'en', 'Consult an expert about a problem you can''t solve alone.', 'Seeking help is a sign of wisdom, not weakness. Professional advice today will save you weeks of trial and error.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('bd85e32e-1631-4220-be6f-521de5519ea8', 'zh', '就一个你无法独立解决的问题咨询行业专家。', '求助是智慧而非软弱。今日的一份专业建议，能为你节省数周的试错成本。');
INSERT INTO omens (id) VALUES ('8e6ccb4d-4cdf-451e-a0d9-d27ba71a7343');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('求子', '8e6ccb4d-4cdf-451e-a0d9-d27ba71a7343');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('8e6ccb4d-4cdf-451e-a0d9-d27ba71a7343', 'en', 'Focus on your legacy and what you want to create next.', 'This energy is about fertility and continuation. It''s a powerful day to conceive a ''brainchild'' or a new creative vision.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('8e6ccb4d-4cdf-451e-a0d9-d27ba71a7343', 'zh', '思考你的长期影响，以及你接下来的创作目标。', '此能量关乎繁衍与延续。今日最宜孕育一个新的‘创意结晶’或宏大的创作愿景。');
INSERT INTO omens (id) VALUES ('db2094d1-3c9a-4c16-8cfa-97df27eccf7c');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('求子', 'db2094d1-3c9a-4c16-8cfa-97df27eccf7c');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('db2094d1-3c9a-4c16-8cfa-97df27eccf7c', 'en', 'Nurture your inner child through a playful activity.', 'To create the new, you must remain young at heart. Today, a playful approach to a difficult task will lead to success.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('db2094d1-3c9a-4c16-8cfa-97df27eccf7c', 'zh', '通过有趣的活动来滋养你的‘内在小孩’。', '欲创万象，必存童心。今日用玩乐的心态去面对难题，反而更容易获得成功。');
INSERT INTO omens (id) VALUES ('27d82729-356d-44d8-8704-690db18545ae');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('求职入学', '27d82729-356d-44d8-8704-690db18545ae');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('27d82729-356d-44d8-8704-690db18545ae', 'en', 'Submit your application to a company that inspires you.', 'Doors of opportunity are swinging open. Today is auspicious for putting your name forward into a new community or role.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('27d82729-356d-44d8-8704-690db18545ae', 'zh', '向那家让你心生向往的公司递交你的申请。', '机遇之门正在缓缓开启。今日利于将你的名号投向新的圈层或职位，寻求突破。');
INSERT INTO omens (id) VALUES ('c68ff214-cc3a-4323-b82e-f46ad32e69b0');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('求职入学', 'c68ff214-cc3a-4323-b82e-f46ad32e69b0');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('c68ff214-cc3a-4323-b82e-f46ad32e69b0', 'en', 'Sign up for a certification that validates your expertise.', 'Entering a new ''school'' of thought is favored. Formalizing your education today increases your future earning power.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('c68ff214-cc3a-4323-b82e-f46ad32e69b0', 'zh', '报名一项能证明你专业水准的资格认证。', '进入新的‘学术门派’受吉星庇佑。今日将你的教育背景正式化，能提升未来的议价能力。');
INSERT INTO omens (id) VALUES ('b055ef4c-4583-4e6c-b00b-0d1a30a6732d');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('沐浴', 'b055ef4c-4583-4e6c-b00b-0d1a30a6732d');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('b055ef4c-4583-4e6c-b00b-0d1a30a6732d', 'en', 'Perform a ''brain dump'' and clear your mental clutter.', 'Bathing is about purification. Washing away stagnant thoughts today allows fresh, clear ideas to emerge.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('b055ef4c-4583-4e6c-b00b-0d1a30a6732d', 'zh', '进行一次‘脑力倾倒’，清空你的心理杂念。', '沐浴意在净化。今日洗去积压的旧思想，能让清新且明晰的创意浮现。');
INSERT INTO omens (id) VALUES ('8f796db9-1eda-4fc5-a8b0-525661525c06');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('沐浴', '8f796db9-1eda-4fc5-a8b0-525661525c06');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('8f796db9-1eda-4fc5-a8b0-525661525c06', 'en', 'Turn off your phone for a long, meditative shower.', 'Water resets your bio-field. A mindful cleanse today will remove the ''static'' of a stressful week.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('8f796db9-1eda-4fc5-a8b0-525661525c06', 'zh', '关掉手机，享受一次长长的冥想式沐浴。', '水能重置你的生物场。今日一份专注的洗练，能帮你洗掉一整周压力积攒的‘静电’。');
INSERT INTO omens (id) VALUES ('3f511e4f-8cc7-48fd-a1ff-17cd16f34661');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('治病', '3f511e4f-8cc7-48fd-a1ff-17cd16f34661');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('3f511e4f-8cc7-48fd-a1ff-17cd16f34661', 'en', 'Implement a radical ''fix'' for a recurring system bug.', 'Treating the illness requires finding the root. Use today to perform ''surgery'' on a part of your life that isn''t working.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('3f511e4f-8cc7-48fd-a1ff-17cd16f34661', 'zh', '为反复出现的系统漏洞实施一次彻底的‘修复’。', '治病求本。今日宜对你生活中那些失效的部分进行一次彻底的‘手术’式整改。');
INSERT INTO omens (id) VALUES ('827a1bfa-d6d2-4193-9ff4-2a8bc74dde6e');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('治病', '827a1bfa-d6d2-4193-9ff4-2a8bc74dde6e');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('827a1bfa-d6d2-4193-9ff4-2a8bc74dde6e', 'en', 'Cut out one habit that you know is harming your focus.', 'Eliminating the cause is the only path to a cure. Today is lucky for quitting a vice and reclaiming your energy.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('827a1bfa-d6d2-4193-9ff4-2a8bc74dde6e', 'zh', '戒掉一个你明知正在损害你专注力的坏习惯。', '除病因方能断病根。今日利于戒除恶习，重新夺回你对自身能量的掌控权。');
INSERT INTO omens (id) VALUES ('9675574a-1323-4e7c-aa2c-38066b25bdea');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('牧养', '9675574a-1323-4e7c-aa2c-38066b25bdea');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('9675574a-1323-4e7c-aa2c-38066b25bdea', 'en', 'Check in on the progress of your long-term passive income.', 'Herding is about managing assets that grow. Today is favored for overseeing things that work for you while you sleep.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('9675574a-1323-4e7c-aa2c-38066b25bdea', 'zh', '检查你长期被动收入项目的进展情况。', '牧养关乎管理成长型资产。今日利于视察那些在你睡觉时也能为你工作的‘赚钱机器’。');
INSERT INTO omens (id) VALUES ('486e58d6-47dd-412c-853a-2d98bf7d623d');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('牧养', '486e58d6-47dd-412c-853a-2d98bf7d623d');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('486e58d6-47dd-412c-853a-2d98bf7d623d', 'en', 'Nurture your team by listening to their individual needs.', 'A healthy flock requires care, not just management. Your leadership thrives today through empathy and support.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('486e58d6-47dd-412c-853a-2d98bf7d623d', 'zh', '倾听团队成员的个人需求，给他们一份关怀。', '健康的‘羊群’需要呵护而非单纯管控。今日你的领导力将通过同理心与支持而得到升华。');
INSERT INTO omens (id) VALUES ('7617563b-2a2d-4fde-8d10-839815b36302');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('理发', '7617563b-2a2d-4fde-8d10-839815b36302');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('7617563b-2a2d-4fde-8d10-839815b36302', 'en', 'Change your physical appearance to mark a fresh start.', 'Cutting hair is an ancient symbol of shedding the past. A fresh look today signals to the world that you''ve evolved.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('7617563b-2a2d-4fde-8d10-839815b36302', 'zh', '改变你的外在形象，以此标志一个新的开始。', '理发是剪除过去的古老象征。今日换个发型，能向世界发出你已进化升级的信号。');
INSERT INTO omens (id) VALUES ('330968f2-1bf6-4585-a4b3-fcfaab88a91c');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('理发', '330968f2-1bf6-4585-a4b3-fcfaab88a91c');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('330968f2-1bf6-4585-a4b3-fcfaab88a91c', 'en', 'Trim the ''dead ends'' of your project''s feature list.', 'Precision requires cutting away the excess. Today is lucky for streamlining your ideas to make them more manageable.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('330968f2-1bf6-4585-a4b3-fcfaab88a91c', 'zh', '修剪掉项目功能列表中那些无用的‘分叉’。', '精准源自精简。今日利于剪掉那些冗余的想法，让你的项目更具可操控性。');
INSERT INTO omens (id) VALUES ('90ac063c-ba3c-419d-885c-755c71cadeb1');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('盖屋', '90ac063c-ba3c-419d-885c-755c71cadeb1');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('90ac063c-ba3c-419d-885c-755c71cadeb1', 'en', 'Consolidate your different projects into one unified brand.', 'Building a house is about creating a singular protective shell. Today is favored for bringing all your efforts under one ''roof''.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('90ac063c-ba3c-419d-885c-755c71cadeb1', 'zh', '将你零散的项目整合进一个统一的品牌之下。', '盖屋意在打造一个统一的庇护壳。今日最利于将你的所有努力整合进同一个品牌主张之下。');
INSERT INTO omens (id) VALUES ('ffc7ae8e-fc13-4f54-8bf0-1c720d5e7992');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('盖屋', 'ffc7ae8e-fc13-4f54-8bf0-1c720d5e7992');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('ffc7ae8e-fc13-4f54-8bf0-1c720d5e7992', 'en', 'Finalize the ''base architecture'' of your digital platform.', 'A roof protects the contents from the elements. Today, prioritize the security and stability of your system''s core structure.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('ffc7ae8e-fc13-4f54-8bf0-1c720d5e7992', 'zh', '敲定你数字化平台的‘基础架构’。', '屋顶保护内部免受风雨。今日应优先考虑系统核心结构的安全性与稳定性。');
INSERT INTO omens (id) VALUES ('7ba2b168-d5a9-4cd2-af71-ce464b821d86');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('破土', '7ba2b168-d5a9-4cd2-af71-ce464b821d86');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('7ba2b168-d5a9-4cd2-af71-ce464b821d86', 'en', 'Conduct a radical post-mortem on a failed initiative.', 'Breaking ground for an ''end'' is about learning from the earth. Deeply analyze past mistakes today to ensure they don''t repeat.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('7ba2b168-d5a9-4cd2-af71-ce464b821d86', 'zh', '对一个失败的倡议进行一次彻底的‘复盘’。', '破土涉及终结，意在从过往中吸取教训。今日深度分析旧错，方能确保其不再重演。');
INSERT INTO omens (id) VALUES ('f356694e-735b-4856-b19b-287bb9ad75b4');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('破土', 'f356694e-735b-4856-b19b-287bb9ad75b4');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('f356694e-735b-4856-b19b-287bb9ad75b4', 'en', 'Delete the legacy code or files that are holding you back.', 'Clearing the space for a grave is about making room for memory. Remove the ''dead weight'' today to lighten your future path.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('f356694e-735b-4856-b19b-287bb9ad75b4', 'zh', '删除那些拖累你进展的旧代码或陈旧文件。', '为归宿清空空间。今日卸下‘死重’包袱，能有效减轻你通往未来的脚步。');
INSERT INTO omens (id) VALUES ('51c487ce-31d8-4b6c-a2e3-afd6b3446bfa');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('破屋', '51c487ce-31d8-4b6c-a2e3-afd6b3446bfa');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('51c487ce-31d8-4b6c-a2e3-afd6b3446bfa', 'en', 'Tear down a restrictive belief or outdated mental model.', 'To rebuild, you must first demolish. Today is the perfect day to challenge and break a system that no longer fits your life.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('51c487ce-31d8-4b6c-a2e3-afd6b3446bfa', 'zh', '拆除一个限制性的信念或陈旧的思维模型。', '欲重建必先拆除。今日最适合挑战并打破那个已经不再适合你生活的旧系统。');
INSERT INTO omens (id) VALUES ('d9b6d88b-93fa-43e7-b5bf-be8257b48277');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('破屋', 'd9b6d88b-93fa-43e7-b5bf-be8257b48277');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('d9b6d88b-93fa-43e7-b5bf-be8257b48277', 'en', 'End a contract or lease that has become a burden.', 'Dismantling a structure releases you from its constraints. Today, break the ties that bind you to a stagnant environment.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('d9b6d88b-93fa-43e7-b5bf-be8257b48277', 'zh', '终止一份已经成为负担的合同或租赁协议。', '拆解旧结构能让你从束缚中解脱。今日宜切断那些将你困在停滞环境中的纽带。');
INSERT INTO omens (id) VALUES ('1c490ea2-4e4e-41cd-8f22-abf8b1548b36');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('祈福', '1c490ea2-4e4e-41cd-8f22-abf8b1548b36');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('1c490ea2-4e4e-41cd-8f22-abf8b1548b36', 'en', 'Set a powerful intention for the month ahead.', 'Aligning your will with the universe brings luck. Today, writing down your desires acts as a formal prayer for success.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('1c490ea2-4e4e-41cd-8f22-abf8b1548b36', 'zh', '为接下来的一个月设定一个强大的意图。', '将意志与宇宙对齐能带来好运。今日写下你的渴望，无异于为成功进行了一场正式的祈祷。');
INSERT INTO omens (id) VALUES ('6165fd91-4474-40a7-863f-2af7bbbcee9d');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('祈福', '6165fd91-4474-40a7-863f-2af7bbbcee9d');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('6165fd91-4474-40a7-863f-2af7bbbcee9d', 'en', 'Practice gratitude by listing five things that went well.', 'Attracting ''blessings'' starts with noticing them. Today, focus on what is working to attract even more positive energy.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('6165fd91-4474-40a7-863f-2af7bbbcee9d', 'zh', '通过列出五件进展顺利的事来练习感恩。', '吸引‘福报’始于觉察。今日专注于那些顺利的事，能为你吸引更多正能量。');
INSERT INTO omens (id) VALUES ('94fb0c46-c7a2-408e-97a7-1e2d432e26ca');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('祭祀', '94fb0c46-c7a2-408e-97a7-1e2d432e26ca');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('94fb0c46-c7a2-408e-97a7-1e2d432e26ca', 'en', 'Pay tribute to a mentor or an inspiration in your field.', 'Honoring your lineage strengthens your own path. Acknowledging those who came before you builds cultural and social capital.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('94fb0c46-c7a2-408e-97a7-1e2d432e26ca', 'zh', '向你领域内的导师或灵感源泉致敬。', '追溯本源能稳固自身道路。今日向先驱致敬，能为你积累深厚的文化与社交资本。');
INSERT INTO omens (id) VALUES ('a0a89cc4-f92d-4441-8110-d05749b0be64');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('祭祀', 'a0a89cc4-f92d-4441-8110-d05749b0be64');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('a0a89cc4-f92d-4441-8110-d05749b0be64', 'en', 'Reflect on your core ''Why'' to reconnect with your passion.', 'Sacrifice is about giving to the source. Today, sacrifice your ego to reconnect with the pure joy of your craft.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('a0a89cc4-f92d-4441-8110-d05749b0be64', 'zh', '反思你的核心‘初心’，重新找回创作热情。', '祭祀是回归本源。今日宜放下小我，找回你投身这项事业最初的纯粹快乐。');
INSERT INTO omens (id) VALUES ('f3cba06e-078c-4e02-bb56-7b67b2fbdafa');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('移柩', 'f3cba06e-078c-4e02-bb56-7b67b2fbdafa');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('f3cba06e-078c-4e02-bb56-7b67b2fbdafa', 'en', 'Migrate your old data to a safer, modern server.', 'Moving a casket is about a final, safe transition. Today is lucky for moving vital assets from an old system to a new one.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('f3cba06e-078c-4e02-bb56-7b67b2fbdafa', 'zh', '将你的旧数据迁移到更安全、更现代的服务器上。', '移柩是关于最终的稳妥转移。今日利于将关键资产从旧系统安全迁移至新系统。');
INSERT INTO omens (id) VALUES ('e22be99a-055a-41db-a663-d44090caa406');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('移柩', 'e22be99a-055a-41db-a663-d44090caa406');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('e22be99a-055a-41db-a663-d44090caa406', 'en', 'Formalize the conclusion of a major business transition.', 'Final movement brings final peace. Use today to complete a complex transition that has been ''in limbo'' for too long.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('e22be99a-055a-41db-a663-d44090caa406', 'zh', '正式确立一项重大商业转型的最终结论。', '最终的移动带来最终的安宁。今日宜完成那个悬而未决太久的复杂转型任务。');
INSERT INTO omens (id) VALUES ('7c8b9816-b129-4ddc-8eab-29a7af8e97f3');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('立碑', '7c8b9816-b129-4ddc-8eab-29a7af8e97f3');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('7c8b9816-b129-4ddc-8eab-29a7af8e97f3', 'en', 'Create a ''Case Study'' of your most successful project.', 'Erecting a monument makes your work permanent. Today is favored for documenting your wins so they stand the test of time.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('7c8b9816-b129-4ddc-8eab-29a7af8e97f3', 'zh', '为你最成功的项目撰写一份‘案例研究’。', '立碑能让你的成就永恒。今日最宜记录你的胜绩，让其经受住时间的考验。');
INSERT INTO omens (id) VALUES ('61b781d7-4bb0-40b9-a105-def54553db06');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('立碑', '61b781d7-4bb0-40b9-a105-def54553db06');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('61b781d7-4bb0-40b9-a105-def54553db06', 'en', 'Register your trademark or buy a domain for your legacy.', 'A monument marks your territory. Today is lucky for claiming a name or space that will define your career for years.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('61b781d7-4bb0-40b9-a105-def54553db06', 'zh', '注册你的商标，或为你的长久事业购买域名。', '碑石标志着领地。今日利于占领那个能定义你多年职业生涯的名称或空间。');
INSERT INTO omens (id) VALUES ('c0bfa6ff-6849-48e7-99a8-d2f1e674ae6b');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('竖柱', 'c0bfa6ff-6849-48e7-99a8-d2f1e674ae6b');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('c0bfa6ff-6849-48e7-99a8-d2f1e674ae6b', 'en', 'Hire a key leader or find a mentor for your business.', 'The pillars support the entire structure. Today is the best day to bring in ''structural'' people who can bear the weight of growth.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('c0bfa6ff-6849-48e7-99a8-d2f1e674ae6b', 'zh', '聘请一位关键领导者，或为你的事业寻找一位导师。', '柱石支撑全局。今日最宜引入那些能分担增长重任、具备‘支柱’属性的人才。');
INSERT INTO omens (id) VALUES ('bef122b3-ac98-4962-9250-e592fe8ac35c');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('竖柱', 'bef122b3-ac98-4962-9250-e592fe8ac35c');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('bef122b3-ac98-4962-9250-e592fe8ac35c', 'en', 'Define the unshakeable ''Pillars'' of your personal brand.', 'Stability requires vertical strength. Today, identify the 3-4 core values that will support every decision you make.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('bef122b3-ac98-4962-9250-e592fe8ac35c', 'zh', '定义你个人品牌中那些不可动摇的‘支柱’理念。', '稳固源自纵向的力量。今日宜确立那 3-4 个核心价值观，让其支撑你的每一个决策。');
INSERT INTO omens (id) VALUES ('fd384990-cd5a-4237-a0b1-cfa163bb24ed');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('筑堤', 'fd384990-cd5a-4237-a0b1-cfa163bb24ed');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('fd384990-cd5a-4237-a0b1-cfa163bb24ed', 'en', 'Setup automated savings to protect against market flux.', 'Building a levee prevents flooding. Today is auspicious for creating financial or operational buffers before ''storms'' arrive.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('fd384990-cd5a-4237-a0b1-cfa163bb24ed', 'zh', '设置自动化储蓄，以抵御市场波动的冲击。', '筑堤意在防洪。今日最宜在‘风暴’到来前，建立起财务或运营上的缓冲带。');
INSERT INTO omens (id) VALUES ('9431f60f-6a09-4a77-974b-65827ec16a3a');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('筑堤', '9431f60f-6a09-4a77-974b-65827ec16a3a');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('9431f60f-6a09-4a77-974b-65827ec16a3a', 'en', 'Strengthen your data backup and recovery systems.', 'A strong dam manages energy. Ensuring your data is ''walled off'' and safe today prevents a catastrophic loss later.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('9431f60f-6a09-4a77-974b-65827ec16a3a', 'zh', '加固你的数据备份与恢复系统。', '坚固的大坝能管理能量。今日确保数据已被‘高墙保护’，能预防未来的灾难性损失。');
INSERT INTO omens (id) VALUES ('e86be44a-6fbe-4214-9712-1db16fed67a8');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('签订合同', 'e86be44a-6fbe-4214-9712-1db16fed67a8');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('e86be44a-6fbe-4214-9712-1db16fed67a8', 'en', 'Sign that partnership agreement you''ve been debating.', 'Commitment creates a new reality. Today the alignment of interests is high, leading to long-term prosperity through collaboration.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('e86be44a-6fbe-4214-9712-1db16fed67a8', 'zh', '签署那份你一直犹豫不决的合伙协议。', '承诺创造现实。今日利益契合度极高，通过协作将带来长期的繁荣。');
INSERT INTO omens (id) VALUES ('4d394c18-d49c-490b-ae81-111d616969bd');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('签订合同', '4d394c18-d49c-490b-ae81-111d616969bd');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('4d394c18-d49c-490b-ae81-111d616969bd', 'en', 'Finalize a deal with a new vendor or supplier.', 'Solidifying your supply chain is favored today. A formal contract signed now ensures a reliable flow of resources.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('4d394c18-d49c-490b-ae81-111d616969bd', 'zh', '与新的供应商或服务商敲定一项交易。', '加固供应链受吉星庇佑。今日签署正式合同，能确保资源的可靠流转。');
INSERT INTO omens (id) VALUES ('ec68f16e-d641-4ef3-a280-5c3b965f6229');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('纳婿', 'ec68f16e-d641-4ef3-a280-5c3b965f6229');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('ec68f16e-d641-4ef3-a280-5c3b965f6229', 'en', 'Invite a new collaborator to join your inner creative circle.', 'Anciently about bringing a son-in-law into the family. Modernly, it is a lucky day for integrating an outsider into your core mission or family business.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('ec68f16e-d641-4ef3-a280-5c3b965f6229', 'zh', '邀请一位新的合作伙伴加入你的核心创意圈。', '古代指招赘女婿。在现代，这是将外部人才整合进你的核心使命或家族事业的吉日。');
INSERT INTO omens (id) VALUES ('e063b161-188c-4d1b-8aa8-a0614f3f3df7');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('纳婿', 'e063b161-188c-4d1b-8aa8-a0614f3f3df7');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('e063b161-188c-4d1b-8aa8-a0614f3f3df7', 'en', 'Onboard a partner who brings resources you currently lack.', 'This is about strengthening your ''house'' through union. Today is auspicious for alliances that fill your skill gaps.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('e063b161-188c-4d1b-8aa8-a0614f3f3df7', 'zh', '入职一位能带来你目前所稀缺资源的合伙人。', '此项活动意在通过联合来壮大‘门楣’。今日利于通过结盟来填补你的技能空白。');
INSERT INTO omens (id) VALUES ('5a15e00b-738b-4473-9fb7-b0f560fb30bb');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('纳畜', '5a15e00b-738b-4473-9fb7-b0f560fb30bb');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('5a15e00b-738b-4473-9fb7-b0f560fb30bb', 'en', 'Invest in a tool or asset that generates passive value.', 'Buying livestock was about acquiring productive assets. Today, focus on ''engines''—whether software or hardware—that work for you.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('5a15e00b-738b-4473-9fb7-b0f560fb30bb', 'zh', '投资一个能产生被动价值的工具或资产。', '买入牲畜是为了获取生产性资产。今日宜关注那些能为你工作的‘引擎’，无论是软件还是硬件。');
INSERT INTO omens (id) VALUES ('fda007c4-5ec6-4d25-a886-cc89f3420bbf');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('纳畜', 'fda007c4-5ec6-4d25-a886-cc89f3420bbf');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('fda007c4-5ec6-4d25-a886-cc89f3420bbf', 'en', 'Adopt a new habit that will ''grow'' your health or wealth.', 'Nurturing something new leads to future abundance. Today is lucky for starting a routine that yields results over time.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('fda007c4-5ec6-4d25-a886-cc89f3420bbf', 'zh', '养成一个能让你的健康或财富‘增值’的新习惯。', '滋养新事物会带来未来的富足。今日最宜开启一套随时间推移而产生复利效应的常规计划。');
INSERT INTO omens (id) VALUES ('39d3b7f7-4bfe-438f-adc2-3284a6c75b8b');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('纳财', '39d3b7f7-4bfe-438f-adc2-3284a6c75b8b');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('39d3b7f7-4bfe-438f-adc2-3284a6c75b8b', 'en', 'Collect outstanding payments or chase up invoices today.', 'The energy of ''receiving'' is at its peak. Today is the best day to pull resources into your accounts and consolidate your gains.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('39d3b7f7-4bfe-438f-adc2-3284a6c75b8b', 'zh', '今日宜收回欠款，或催收逾期发票。', '‘收纳’的能量处于巅峰。今日是将资源汇入账簿、巩固收益的最佳时机。');
INSERT INTO omens (id) VALUES ('930bc698-49ea-428f-9b8c-eecf7850cdb4');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('纳财', '930bc698-49ea-428f-9b8c-eecf7850cdb4');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('930bc698-49ea-428f-9b8c-eecf7850cdb4', 'en', 'Accept a new job offer or a high-value project quote.', 'Opening the door to wealth is favored today. Say yes to opportunities that increase your net worth.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('930bc698-49ea-428f-9b8c-eecf7850cdb4', 'zh', '接受一份新的工作邀约或高价值的项目报价。', '开启财富之门受吉星庇佑。今日宜对那些能提升你净值的机会说‘好’。');
INSERT INTO omens (id) VALUES ('64dfb534-698c-4b9c-ab37-15ac55aeb973');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('结婚', '64dfb534-698c-4b9c-ab37-15ac55aeb973');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('64dfb534-698c-4b9c-ab37-15ac55aeb973', 'en', 'Merge your efforts with a partner for a massive launch.', 'Union creates exponential power. Today is lucky for ''marrying'' two different ideas or brands to create something bigger.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('64dfb534-698c-4b9c-ab37-15ac55aeb973', 'zh', '与合作伙伴合力，开启一次重大的发布活动。', '联合能产生指数级的力量。今日利于将两个不同的创意或品牌‘联姻’，创造更大的价值。');
INSERT INTO omens (id) VALUES ('e6f2f678-aaf7-457e-bcaa-1e4408450a99');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('结婚', 'e6f2f678-aaf7-457e-bcaa-1e4408450a99');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('e6f2f678-aaf7-457e-bcaa-1e4408450a99', 'en', 'Commit to a long-term professional or personal vow.', 'The universe favors binding agreements today. Formalizing a deep commitment ensures it stands the test of time.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('e6f2f678-aaf7-457e-bcaa-1e4408450a99', 'zh', '许下一个长期的职业或个人承诺。', '宇宙今日利于达成具有约束力的协议。正式化一个深层的承诺，能确保其经受住时间的考验。');
INSERT INTO omens (id) VALUES ('68d05faa-4063-47ed-a98b-5dc6e05975ab');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('结网', '68d05faa-4063-47ed-a98b-5dc6e05975ab');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('68d05faa-4063-47ed-a98b-5dc6e05975ab', 'en', 'Build a new automated sales funnel or mailing list.', 'Making a net is about preparing to catch opportunity. Today is for building systems that capture leads while you sleep.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('68d05faa-4063-47ed-a98b-5dc6e05975ab', 'zh', '搭建一个新的自动化销售漏斗或邮件列表。', '结网意在准备捕获机遇。今日宜搭建那些能在你休息时自动捕捉潜在客户的系统。');
INSERT INTO omens (id) VALUES ('61026b23-da45-4d63-b089-e7f182acae31');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('结网', '61026b23-da45-4d63-b089-e7f182acae31');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('61026b23-da45-4d63-b089-e7f182acae31', 'en', 'Update your LinkedIn or professional networking profile.', 'Strengthening your ''web'' connects you to more prey. Use today to broaden your professional reach and visibility.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('61026b23-da45-4d63-b089-e7f182acae31', 'zh', '更新你的 LinkedIn 或专业社交媒体资料。', '加固你的‘关系网’能让你接触到更多机会。今日宜扩大你的职业影响范围和曝光度。');
INSERT INTO omens (id) VALUES ('7d9a141e-6ba9-4dd4-b0ce-415e7c95a93e');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('美甲浴足', '7d9a141e-6ba9-4dd4-b0ce-415e7c95a93e');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('7d9a141e-6ba9-4dd4-b0ce-415e7c95a93e', 'en', 'Take a ''maintenance day'' to prevent creative burnout.', 'Self-care is a prerequisite for performance. Grooming your physical self today refreshes your mental edge for the week ahead.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('7d9a141e-6ba9-4dd4-b0ce-415e7c95a93e', 'zh', '安排一个‘维护日’，预防创作倦怠。', '自我关怀是高效表现的前提。今日修饰仪容、放松身心，能为下周的工作磨利你的‘思维之刃’。');
INSERT INTO omens (id) VALUES ('bd5c1b94-acfc-49f8-b6eb-3e164675c9e5');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('美甲浴足', 'bd5c1b94-acfc-49f8-b6eb-3e164675c9e5');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('bd5c1b94-acfc-49f8-b6eb-3e164675c9e5', 'en', 'Pay attention to the small, aesthetic details of your project.', 'Small refinements make a big difference. Today is lucky for ''polishing'' the edges of your work until it shines.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('bd5c1b94-acfc-49f8-b6eb-3e164675c9e5', 'zh', '关注你项目中那些细微的美学细节。', '细节决定成败。今日利于‘打磨’作品的边缘细节，直至其焕发光彩。');
INSERT INTO omens (id) VALUES ('18b370c3-3f45-4858-b43c-1a3d5d5aeab7');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('补垣', '18b370c3-3f45-4858-b43c-1a3d5d5aeab7');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('18b370c3-3f45-4858-b43c-1a3d5d5aeab7', 'en', 'Fix the security vulnerabilities in your digital life.', 'Mending a wall prevents loss. Today is auspicious for changing passwords or updating firewall settings.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('18b370c3-3f45-4858-b43c-1a3d5d5aeab7', 'zh', '修复你数字生活中的安全漏洞。', '补墙意在防范流失。今日最宜更改密码或更新防火墙设置，加固安全。 ');
INSERT INTO omens (id) VALUES ('cf6c9f57-45ab-4351-b955-e187121152f2');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('补垣', 'cf6c9f57-45ab-4351-b955-e187121152f2');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('cf6c9f57-45ab-4351-b955-e187121152f2', 'en', 'Mend a strained professional relationship with a short note.', 'A small repair today prevents a total collapse tomorrow. Use today to patch up misunderstandings or gaps in communication.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('cf6c9f57-45ab-4351-b955-e187121152f2', 'zh', '通过简单的讯息，修复一段紧张的职场关系。', '今日的小修小补能防止明日的彻底崩塌。宜通过沟通弥合误解或信息断层。');
INSERT INTO omens (id) VALUES ('86591da3-962c-4a43-b0d2-e9e6e707847f');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('装修', '86591da3-962c-4a43-b0d2-e9e6e707847f');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('86591da3-962c-4a43-b0d2-e9e6e707847f', 'en', 'Redesign your landing page or app interface for better UX.', 'Improving the ''facade'' attracts better energy. Today is lucky for visual upgrades that make your work more inviting.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('86591da3-962c-4a43-b0d2-e9e6e707847f', 'zh', '重新设计你的落地页或 App 界面以提升用户体验。', '改善‘门面’能吸引更佳的能量。今日利于视觉升级，让你的作品更具吸引力。');
INSERT INTO omens (id) VALUES ('1d443e5b-394c-460a-b16b-bb79002943f3');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('装修', '1d443e5b-394c-460a-b16b-bb79002943f3');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('1d443e5b-394c-460a-b16b-bb79002943f3', 'en', 'Update your environment with better lighting or art.', 'Beauty fuels productivity. Enhancing your surroundings today will directly impact your creative output tomorrow.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('1d443e5b-394c-460a-b16b-bb79002943f3', 'zh', '通过更好的灯光或艺术品来升级你的环境。', '美感能驱动生产力。今日提升环境品质，将直接影响你明天的创作产出。');
INSERT INTO omens (id) VALUES ('275b1a34-13bd-4d4c-ba54-2dbf32640eb9');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('订盟', '275b1a34-13bd-4d4c-ba54-2dbf32640eb9');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('275b1a34-13bd-4d4c-ba54-2dbf32640eb9', 'en', 'Announce a strategic partnership or collaboration.', 'Forming an alliance is a power move. Today is lucky for public declarations of shared goals and mutual support.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('275b1a34-13bd-4d4c-ba54-2dbf32640eb9', 'zh', '宣布一项战略合作伙伴关系或协作计划。', '结盟是一项有力的策略。今日利于公开声明共同目标与相互支持，确立盟约。');
INSERT INTO omens (id) VALUES ('600ecd87-118d-43df-bb1a-3c22b7b8c7b0');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('订盟', '600ecd87-118d-43df-bb1a-3c22b7b8c7b0');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('600ecd87-118d-43df-bb1a-3c22b7b8c7b0', 'en', 'Sign a Letter of Intent for a future acquisition or deal.', 'Setting a formal path for union is favored. Today is for aligning ''intent'' before the final contract is written.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('600ecd87-118d-43df-bb1a-3c22b7b8c7b0', 'zh', '为未来的收购或交易签署一份意向书。', '为联合设定正式路径受吉星庇佑。今日宜在正式合同签署前，先达成‘意向’上的对齐。');
INSERT INTO omens (id) VALUES ('852e1040-4bfa-45d0-b888-038fa9ed4969');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('谢土', '852e1040-4bfa-45d0-b888-038fa9ed4969');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('852e1040-4bfa-45d0-b888-038fa9ed4969', 'en', 'Send a thank-you note to someone who helped you build.', 'Anciently a ceremony to thank the earth after building. Today, acknowledging your support system ensures future luck.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('852e1040-4bfa-45d0-b888-038fa9ed4969', 'zh', '给曾经帮助你创业或建设的人发一封感谢信。', '古代指工程完工后祭谢土地。今日通过感恩你的支持系统，能为未来积攒好运。');
INSERT INTO omens (id) VALUES ('817ff563-0c58-44b9-b603-d1e7582fcff4');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('谢土', '817ff563-0c58-44b9-b603-d1e7582fcff4');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('817ff563-0c58-44b9-b603-d1e7582fcff4', 'en', 'Review a completed project and acknowledge what you learned.', 'Gratitude closes the loop and invites new projects. Use today to honor the ''ground'' that hosted your recent success.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('817ff563-0c58-44b9-b603-d1e7582fcff4', 'zh', '回顾一个已完成的项目，并确认你从中收到的启发。', '感恩能完成闭环并引来新项目。今日宜向促成你近期成功的‘基石’致敬。');
INSERT INTO omens (id) VALUES ('01bfa22e-99b0-48da-880b-0d8dcb5be715');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('赴任', '01bfa22e-99b0-48da-880b-0d8dcb5be715');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('01bfa22e-99b0-48da-880b-0d8dcb5be715', 'en', 'Step into a leadership role or start your first day at a new job.', 'Taking office is about assuming authority. Today is auspicious for setting the tone of your leadership and making a strong first impression.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('01bfa22e-99b0-48da-880b-0d8dcb5be715', 'zh', '今日宜走马上任，或开启新职位的首日工作。', '赴任关乎确立权威。今日最宜奠定你的领导基调，并给团队留下深刻的第一印象。');
INSERT INTO omens (id) VALUES ('a722933e-ab96-48e4-b7cc-bc5dce0e8246');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('赴任', 'a722933e-ab96-48e4-b7cc-bc5dce0e8246');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('a722933e-ab96-48e4-b7cc-bc5dce0e8246', 'en', 'Accept a new set of responsibilities with a formal plan.', 'Responsibility is the precursor to growth. Today is lucky for taking the reins of a project and steering it toward your vision.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('a722933e-ab96-48e4-b7cc-bc5dce0e8246', 'zh', '带着正式计划去接手一组全新的职责。', '责任是成长的先导。今日利于接管项目主导权，并按照你的愿景指引航向。');
INSERT INTO omens (id) VALUES ('99711d0a-89c7-4e7d-b3b0-1eded166d357');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('起基', '99711d0a-89c7-4e7d-b3b0-1eded166d357');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('99711d0a-89c7-4e7d-b3b0-1eded166d357', 'en', 'Finalize the mission statement or core values of your startup.', 'Laying the foundation is about defining the ''why''. Today is lucky for setting the unshakeable principles that will support your future empire.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('99711d0a-89c7-4e7d-b3b0-1eded166d357', 'zh', '敲定你初创公司的使命宣言或核心价值观。', '起基关乎定义‘初衷’。今日利于确立那些不可动摇的原则，支撑起你未来的事业版图。');
INSERT INTO omens (id) VALUES ('2479aa4e-bb29-44c9-bee8-d2cecd9705b2');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('起基', '2479aa4e-bb29-44c9-bee8-d2cecd9705b2');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('2479aa4e-bb29-44c9-bee8-d2cecd9705b2', 'en', 'Draft the initial architecture for a new app or system.', 'Every great structure starts underground. Use today to focus on the invisible logic that makes your visible work possible.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('2479aa4e-bb29-44c9-bee8-d2cecd9705b2', 'zh', '为一个新应用或系统起草最初的底层架构。', '万丈高楼起于地下。今日宜专注于那些不可见的底层逻辑，它们是后续开发的基础。');
INSERT INTO omens (id) VALUES ('7e203cb3-ad92-4800-91b6-a7f7f3a2eb2f');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('迁坟', '7e203cb3-ad92-4800-91b6-a7f7f3a2eb2f');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('7e203cb3-ad92-4800-91b6-a7f7f3a2eb2f', 'en', 'Clean up your digital archives and move them to a better storage.', 'Moving a resting place is about optimizing the environment for the past. Today is lucky for re-organizing old assets to protect them for the future.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('7e203cb3-ad92-4800-91b6-a7f7f3a2eb2f', 'zh', '清理你的数字档案，并将其迁移到更好的存储介质中。', '迁坟意在优化先人的环境。今日利于重整旧资产，通过更有序的存储方式为未来做好保护。');
INSERT INTO omens (id) VALUES ('8fdb607c-a575-479f-b7ac-a3589cf56380');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('迁坟', '8fdb607c-a575-479f-b7ac-a3589cf56380');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('8fdb607c-a575-479f-b7ac-a3589cf56380', 'en', 'Update the documentation for a legacy project.', 'Respecting what came before prevents future confusion. Today, clarifying the history of your work ensures it remains useful as you move on.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('8fdb607c-a575-479f-b7ac-a3589cf56380', 'zh', '为某个遗留项目更新其技术文档。', '尊重过往方能避免未来的混乱。今日理清工作史，能确保这些成果在你离任后依然发挥作用。');
INSERT INTO omens (id) VALUES ('2d5ca2ab-7123-48cd-967c-06f117cdd832');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('造仓', '2d5ca2ab-7123-48cd-967c-06f117cdd832');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('2d5ca2ab-7123-48cd-967c-06f117cdd832', 'en', 'Set up an automated emergency fund or savings vault.', 'Building a granary is about securing your surplus. Today is favored for creating systems that hold and protect your resources.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('2d5ca2ab-7123-48cd-967c-06f117cdd832', 'zh', '设置一个自动化的紧急基金或储蓄金库。', '造仓关乎保障余粮。今日最利于建立那些能够留存并保护你资源的系统。');
INSERT INTO omens (id) VALUES ('968041d5-51ac-46ef-919f-1ec8e873fcb5');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('造仓', '968041d5-51ac-46ef-919f-1ec8e873fcb5');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('968041d5-51ac-46ef-919f-1ec8e873fcb5', 'en', 'Invest in a high-capacity backup drive or cloud storage plan.', 'Storage is the modern granary. Today is lucky for increasing your capacity to hold data, knowledge, or capital.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('968041d5-51ac-46ef-919f-1ec8e873fcb5', 'zh', '投资一个大容量备份硬盘或云存储计划。', '存储是现代的粮仓。今日利于扩充你承载数据、知识或资本的容量。');
INSERT INTO omens (id) VALUES ('b6e9eb5d-4349-4485-a4fa-394d957d6e43');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('造庙', 'b6e9eb5d-4349-4485-a4fa-394d957d6e43');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('b6e9eb5d-4349-4485-a4fa-394d957d6e43', 'en', 'Create a space or community for shared values and inspiration.', 'Building a temple is about creating a home for the spirit. Today is lucky for projects that unite people around a higher purpose.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('b6e9eb5d-4349-4485-a4fa-394d957d6e43', 'zh', '为一个共同的价值观或灵感源泉创建一个空间/社区。', '造庙意在为精神安家。今日利于那些能将人们聚集在更高使命之下的项目。');
INSERT INTO omens (id) VALUES ('0340927a-ce0e-44ed-b719-e972fd784bc2');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('造庙', '0340927a-ce0e-44ed-b719-e972fd784bc2');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('0340927a-ce0e-44ed-b719-e972fd784bc2', 'en', 'Define the ''guiding principles'' of your creative community.', 'Structure supports belief. Today is auspicious for establishing the rituals and rules that foster long-term collective growth.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('0340927a-ce0e-44ed-b719-e972fd784bc2', 'zh', '为你所在的创意社区定义‘指导原则’。', '结构支撑信仰。今日利于建立那些能促进集体长期增长的仪式与规则。');
INSERT INTO omens (id) VALUES ('a134fb31-9d73-4784-bea2-a26afd13cac0');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('造桥', 'a134fb31-9d73-4784-bea2-a26afd13cac0');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('a134fb31-9d73-4784-bea2-a26afd13cac0', 'en', 'Facilitate a connection between two people in your network.', 'A bridge overcomes a gap. Today, being the ''connector'' who helps others reach their goals will build your own social capital.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('a134fb31-9d73-4784-bea2-a26afd13cac0', 'zh', '在你的社交圈中促成两个人的资源对接。', '造桥意在跨越鸿沟。今日通过引荐资源帮助他人，将极大地积累你个人的社交资本。');
INSERT INTO omens (id) VALUES ('5a1e25a2-2aeb-4e55-a165-2bb5c7f8e0d7');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('造桥', '5a1e25a2-2aeb-4e55-a165-2bb5c7f8e0d7');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('5a1e25a2-2aeb-4e55-a165-2bb5c7f8e0d7', 'en', 'Integrate two separate apps or systems via an API.', 'Connecting flows creates efficiency. Today is lucky for engineering pathways that allow data and value to travel faster.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('5a1e25a2-2aeb-4e55-a165-2bb5c7f8e0d7', 'zh', '通过 API 将两个独立的应用或系统进行打通。', '连通流向能创造效率。今日利于设计技术路径，让数据和价值流转得更顺畅。');
INSERT INTO omens (id) VALUES ('92e9763c-1523-4b77-9602-de90e3beaf54');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('造畜稠', '92e9763c-1523-4b77-9602-de90e3beaf54');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('92e9763c-1523-4b77-9602-de90e3beaf54', 'en', 'Optimize the environment for your creative ''assets''.', 'Providing a home for livestock ensures their productivity. Today, organize your tools so they are ready for action whenever you are.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('92e9763c-1523-4b77-9602-de90e3beaf54', 'zh', '为你手头的创意‘资产’优化其生存与产出环境。', '为牲畜造圈意在保障产出。今日宜整理你的生产工具，确保它们随时处于待命状态。');
INSERT INTO omens (id) VALUES ('2662f3f7-5499-4ea7-b581-1e88e91ee62b');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('造畜稠', '2662f3f7-5499-4ea7-b581-1e88e91ee62b');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('2662f3f7-5499-4ea7-b581-1e88e91ee62b', 'en', 'Streamline the management of your small investments.', 'Careful housing prevents loss. Today is auspicious for checking in on the ''small things'' that aggregate into your total wealth.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('2662f3f7-5499-4ea7-b581-1e88e91ee62b', 'zh', '精简并优化你那些小额投资的管理流程。', '妥善安顿方能防范流失。今日利于视察那些积少成多的资产项，确保其稳健增长。');
INSERT INTO omens (id) VALUES ('eb1c61e8-2707-446b-9534-528483f6fe0a');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('造船', 'eb1c61e8-2707-446b-9534-528483f6fe0a');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('eb1c61e8-2707-446b-9534-528483f6fe0a', 'en', 'Start building the platform that will carry your ideas to market.', 'A ship is a vessel for long journeys. Today is favored for starting the development of products that cross boundaries and reach new audiences.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('eb1c61e8-2707-446b-9534-528483f6fe0a', 'zh', '开始搭建那个能将你的创意推向市场的平台。', '船是远航的载体。今日最宜启动那些能够跨越边界、触达新受众的产品开发工作。');
INSERT INTO omens (id) VALUES ('7e64a1ca-754f-48f4-9ed7-a88ade97da04');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('造船', '7e64a1ca-754f-48f4-9ed7-a88ade97da04');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('7e64a1ca-754f-48f4-9ed7-a88ade97da04', 'en', 'Invest in a new computer or tech gear for your career.', 'A superior vessel handles rougher seas. Today is lucky for upgrading the hardware you rely on for your daily ''voyage''.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('7e64a1ca-754f-48f4-9ed7-a88ade97da04', 'zh', '为你的职业生涯投资一台新电脑或科技装备。', '工欲善其事，必先利其器。今日利于升级那些支撑你每日‘航行’的核心硬件设备。');
INSERT INTO omens (id) VALUES ('584da761-ba68-48d5-90b2-1aa375ca1976');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('造车器', '584da761-ba68-48d5-90b2-1aa375ca1976');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('584da761-ba68-48d5-90b2-1aa375ca1976', 'en', 'Automate a tedious part of your creative process.', 'Making tools for transport increases personal velocity. Today, building a script or macro is like adding wheels to your project.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('584da761-ba68-48d5-90b2-1aa375ca1976', 'zh', '将你创作过程中一个乏味的环节自动化。', '制造车辆零件能提升个人速度。今日编写一段脚本或宏，就像是给你的项目装上了轮子。');
INSERT INTO omens (id) VALUES ('4568d00c-4db6-45ad-8067-df214c222e1a');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('造车器', '4568d00c-4db6-45ad-8067-df214c222e1a');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('4568d00c-4db6-45ad-8067-df214c222e1a', 'en', 'Refine the most repetitive steps of your daily routine.', 'Efficiency is the engine of success. Today is lucky for ''machining'' a smoother way to handle your high-frequency tasks.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('4568d00c-4db6-45ad-8067-df214c222e1a', 'zh', '提炼并优化你日常流程中那些重复性最高的操作。', '效率是成功的引擎。今日利于针对高频任务，磨练出一套更顺滑的处理方式。');
INSERT INTO omens (id) VALUES ('7105babf-aa63-4dc9-a801-2b2a73baeb04');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('针灸', '7105babf-aa63-4dc9-a801-2b2a73baeb04');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('7105babf-aa63-4dc9-a801-2b2a73baeb04', 'en', 'Find the single ''pressure point'' that is blocking your project.', 'Acupuncture is about precision release. Today, identifying the one small bottleneck and fixing it will restore the flow of your entire system.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('7105babf-aa63-4dc9-a801-2b2a73baeb04', 'zh', '找出阻碍你项目进展的那一个‘痛点’。', '针灸意在精准释放。今日找出那个关键的‘瓶颈’并予以解决，将使你的整个系统恢复活力。');
INSERT INTO omens (id) VALUES ('e40106cf-4b26-43de-93c0-d4ad19960278');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('针灸', 'e40106cf-4b26-43de-93c0-d4ad19960278');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('e40106cf-4b26-43de-93c0-d4ad19960278', 'en', 'Schedule a session with a specialist to fix a recurring pain.', 'Direct intervention is favored today. Don''t mask the symptom; use today to apply a precise remedy to a long-standing issue.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('e40106cf-4b26-43de-93c0-d4ad19960278', 'zh', '预约一位专家，去解决那个反复出现的痛点问题。', '今日利于直接干预。不要掩盖症状，而要针对顽疾应用最精准的补救措施。');
INSERT INTO omens (id) VALUES ('1d290e54-9659-4990-a2d2-bcd1d7a386fe');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('铺路', '1d290e54-9659-4990-a2d2-bcd1d7a386fe');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('1d290e54-9659-4990-a2d2-bcd1d7a386fe', 'en', 'Standardize your onboarding process for new clients or users.', 'Paving a road makes the journey smooth for others. Today is auspicious for creating clear pathways that reduce friction for your audience.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('1d290e54-9659-4990-a2d2-bcd1d7a386fe', 'zh', '为新客户或用户标准化你的入职流程。', '铺路意在为他人提供坦途。今日利于建立清晰的指引流程，以此降低受众进入你领域的门槛。');
INSERT INTO omens (id) VALUES ('35d25341-5535-4e22-81c5-79f8151d8c78');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('铺路', '35d25341-5535-4e22-81c5-79f8151d8c78');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('35d25341-5535-4e22-81c5-79f8151d8c78', 'en', 'Write a ''How-To'' guide or documentation for your team.', 'Success is easier when the path is marked. Today, documenting your process ensures that the momentum continues even when you aren''t there.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('35d25341-5535-4e22-81c5-79f8151d8c78', 'zh', '为你的团队编写一份操作指南或技术文档。', '路径明确，成功更易。今日记录你的操作流程，能确保即便你不在场，事业也能顺畅运行。');
INSERT INTO omens (id) VALUES ('3d907cd5-472c-4180-9bac-248e28930195');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('问名', '3d907cd5-472c-4180-9bac-248e28930195');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('3d907cd5-472c-4180-9bac-248e28930195', 'en', 'Conduct a deep background check or research on a potential partner.', 'Anciently about verifying identities before marriage. Modernly, it is a lucky day for due diligence to ensure values are truly aligned.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('3d907cd5-472c-4180-9bac-248e28930195', 'zh', '对潜在的合作伙伴进行一次深度的背景调查或调研。', '古代指婚前询问姓名资历。在现代，这是进行尽职调查、确保双方价值观真正契合的吉日。');
INSERT INTO omens (id) VALUES ('4ecbac38-bff9-4825-834a-65d3e121bbd0');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('问名', '4ecbac38-bff9-4825-834a-65d3e121bbd0');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('4ecbac38-bff9-4825-834a-65d3e121bbd0', 'en', 'Register a new brand name or verify domain availability.', 'A name carries destiny. Today is favored for claiming a title or identity that perfectly encapsulates your vision.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('4ecbac38-bff9-4825-834a-65d3e121bbd0', 'zh', '注册一个新的品牌名称，或验证域名的可用性。', '名字承载天命。今日利于锁定那个能完美概括你愿景的头衔或身份标识。');
INSERT INTO omens (id) VALUES ('fc37c12a-d4ed-4d33-a1ff-29e1374c7a19');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('除服', 'fc37c12a-d4ed-4d33-a1ff-29e1374c7a19');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('fc37c12a-d4ed-4d33-a1ff-29e1374c7a19', 'en', 'Shed an old professional title and embrace your new role.', 'Removing mourning garments marks the end of a restriction. Today, formally step out of the ''shadow'' of your past work and into your new light.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('fc37c12a-d4ed-4d33-a1ff-29e1374c7a19', 'zh', '卸下旧的职业头衔，全身心拥抱你的新角色。', '除服标志着限制期的终结。今日宜正式走出过去工作的‘阴影’，步入全新的高光时刻。');
INSERT INTO omens (id) VALUES ('5666fb10-9516-4aad-b8a9-be83cc02a3f5');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('除服', '5666fb10-9516-4aad-b8a9-be83cc02a3f5');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('5666fb10-9516-4aad-b8a9-be83cc02a3f5', 'en', 'Update your social media handles to reflect who you are now.', 'Changing your outward ''uniform'' signals evolution. Use today to tell the world that a cycle has ended and a new one has begun.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('5666fb10-9516-4aad-b8a9-be83cc02a3f5', 'zh', '更新你的社交媒体账号信息，反映你现在的真实状态。', '改变外在的‘制服’预示着进化。今日宜向外界宣告一个旧周期的结束与新周期的开启。');
INSERT INTO omens (id) VALUES ('2402d65c-a4bd-4266-ae68-628cc88581e2');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('除虫', '2402d65c-a4bd-4266-ae68-628cc88581e2');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('2402d65c-a4bd-4266-ae68-628cc88581e2', 'en', 'Run a security scan and delete malware or tracking cookies.', 'Pest control prevents invisible damage. Today is auspicious for a ''digital deep clean'' to ensure your systems remain fast and private.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('2402d65c-a4bd-4266-ae68-628cc88581e2', 'zh', '进行一次安全扫描，删除恶意软件或追踪插件。', '除虫意在防范隐形损害。今日利于‘数字大扫除’，确保系统运行飞快且隐私无忧。');
INSERT INTO omens (id) VALUES ('33342fa6-2e67-44ed-a457-545c80411182');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('除虫', '33342fa6-2e67-44ed-a457-545c80411182');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('33342fa6-2e67-44ed-a457-545c80411182', 'en', 'Identify and stop a small, repetitive ''drain'' on your focus.', 'Small pests destroy the harvest. Today, eliminate one minor but persistent distraction to save your creative energy.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('33342fa6-2e67-44ed-a457-545c80411182', 'zh', '识别并切断一个细小但反复出现的‘专注力黑洞’。', '微小的害虫也会毁掉收成。今日宜铲除那个微小但顽固的干扰源，夺回你的创作能量。');
INSERT INTO omens (id) VALUES ('44647812-d1eb-4e97-97e8-11bf780f2d4c');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('雇庸', '44647812-d1eb-4e97-97e8-11bf780f2d4c');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('44647812-d1eb-4e97-97e8-11bf780f2d4c', 'en', 'Outsource a task that is below your current skill level.', 'Hiring help is about leveraging your time. Today is lucky for finding a Virtual Assistant or freelancer to handle the boilerplate.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('44647812-d1eb-4e97-97e8-11bf780f2d4c', 'zh', '将一项低于你目前专业水平的任务外包出去。', '雇庸意在杠杆化你的时间。今日利于寻找虚拟助手或自由职业者来处理那些琐碎的常规工作。');
INSERT INTO omens (id) VALUES ('0b61dc50-06df-4d90-a4d7-b940ba3ee7c8');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('雇庸', '0b61dc50-06df-4d90-a4d7-b940ba3ee7c8');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('0b61dc50-06df-4d90-a4d7-b940ba3ee7c8', 'en', 'Hire a specialist to solve a problem that has stalled you.', 'Buying expertise is the fastest way to grow. Today, investing in professional labor will yield a 10x return on your speed.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('0b61dc50-06df-4d90-a4d7-b940ba3ee7c8', 'zh', '聘请一位专家来解决那个让你停滞不前的难题。', '购买专业经验是增长的最快路径。今日在专业人力上的投入，将为你带来十倍的速度回报。');
INSERT INTO omens (id) VALUES ('958108f1-d1fb-441b-bacd-275ff2b05dbc');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('雕刻', '958108f1-d1fb-441b-bacd-275ff2b05dbc');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('958108f1-d1fb-441b-bacd-275ff2b05dbc', 'en', 'Refine the most important sentence of your project''s copy.', 'Carving requires patience and precision. Today is favored for ''chiseling'' away the fluff until only the powerful essence remains.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('958108f1-d1fb-441b-bacd-275ff2b05dbc', 'zh', '精雕细琢你项目文案中最关键的那一句话。', '雕刻需要耐心与精准。今日利于‘凿掉’那些赘述，直到只剩下最核心、最有力量的精华。');
INSERT INTO omens (id) VALUES ('ad192439-75d7-4e13-b8bb-dd4543a60615');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('雕刻', 'ad192439-75d7-4e13-b8bb-dd4543a60615');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('ad192439-75d7-4e13-b8bb-dd4543a60615', 'en', 'Add the final aesthetic ''polish'' to your design or product.', 'Detailing creates value. Today is lucky for those tiny adjustments that make a product feel premium and intentional.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('ad192439-75d7-4e13-b8bb-dd4543a60615', 'zh', '为你的设计或产品添加最后的视觉‘磨光’。', '细节创造价值。今日利于进行那些微小的调整，让产品散发出某种高级感与匠心。');
INSERT INTO omens (id) VALUES ('ae54c7c5-a6d8-4f8b-ab2f-2d45203ea172');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('馀事勿取', 'ae54c7c5-a6d8-4f8b-ab2f-2d45203ea172');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('ae54c7c5-a6d8-4f8b-ab2f-2d45203ea172', 'en', 'Stick to your existing schedule; do not start anything new.', 'When only routine is favored, deviation leads to chaos. Use today to master your current tasks without adding to your plate.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('ae54c7c5-a6d8-4f8b-ab2f-2d45203ea172', 'zh', '坚持现有的日程安排；今日不宜开启任何新计划。', '当仅利于常规时，偏离轨迹会导致混乱。今日宜深耕手头工作，不要给自己增加额外负担。');
INSERT INTO omens (id) VALUES ('8c958ad3-e2e4-4de5-913d-0de892263721');
INSERT INTO suit_activity_omens (suit_key, omen_id) VALUES ('馀事勿取', '8c958ad3-e2e4-4de5-913d-0de892263721');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('8c958ad3-e2e4-4de5-913d-0de892263721', 'en', 'Decline all new invites and focus purely on maintenance.', 'The energy today is for preservation, not expansion. Say ''no'' to new opportunities so you can properly protect what you''ve already built.');
INSERT INTO omen_translations (omen_id, language_code, omen_text, explanation) VALUES ('8c958ad3-e2e4-4de5-913d-0de892263721', 'zh', '拒绝所有新的邀约，纯粹专注于日常维护工作。', '今日的能量利于守成而非扩张。对新机会说‘不’，是为了更好地保护你已打下的江山。');